	writeFileCS(t, dir, "parent.txt", "parent amended\n")
	gitRunCS(t, dir, "add", ".")
	gitRunCS(t, dir, "commit", "--amend", "-m", "amended parent")
	parentSHA2 := gitSHA(t, dir, "parent")

