	fp := setupFeaturePath(t, dir)

	// Create two branches that will conflict
	createStackBranch(t, dir, "b1", "main", "shared.txt", "b1 content\n")
	gitRunCS(t, dir, "checkout", "main")
	gitRunCS(t, dir, "checkout", "-b", "b2")
	writeFileCS(t, dir, "shared2.txt", "b2 content\n")
	gitRunCS(t, dir, "add", ".")
	gitRunCS(t, dir, "commit", "-m", "b2")

	// Advance main with conflicting content
	gitRunCS(t, dir, "checkout", "main")
	writeFileCS(t, dir, "shared.txt", "main conflict\n")
	writeFileCS(t, dir, "shared2.txt", "main conflict2\n")
	gitRunCS(t, dir, "add", ".")
	gitRunCS(t, dir, "commit", "-m", "conflict on main")

	saveTestStack(t, fp, []internal.StackEntry{
		{Name: "b1", Base: "main"},
		{Name: "b2", Base: "main"},
	})

	opts := internal.CheckoutSyncOpts{
		Feature:     "test-feature",
		FeaturePath: fp,
		RepoDir:     dir,
	}

	// First conflict
	err := internal.RunCheckoutSync(opts)
	if err == nil {
		t.Fatal("expected conflict")
	}

	// Resolve first conflict
	writeFileCS(t, dir, "shared.txt", "resolved\n")
	gitRunCS(t, dir, "add", ".")
	gitRunCS(t, dir, "rebase", "--continue")

	// Continue - second branch might also conflict
	err = internal.ContinueCheckoutSync(opts)
	if err != nil {
		if strings.Contains(err.Error(), "conflict") {
			// Resolve second conflict
			writeFileCS(t, dir, "shared2.txt", "resolved2\n")
			gitRunCS(t, dir, "add", ".")
			gitRunCS(t, dir, "rebase", "--continue")
			err = internal.ContinueCheckoutSync(opts)
		}
	}
	if err != nil {
		t.Fatalf("should succeed after resolving conflicts: %v", err)
	}
}

// ---------- Test: restoration retry ----------

func TestCheckoutSync_RestorationRetry(t *testing.T) {
	clearStepHook(t)
	dir := setupCheckoutSyncRepo(t)
	fp := setupFeaturePath(t, dir)

	createStackBranch(t, dir, "child", "main", "child.txt", "child\n")
	gitRunCS(t, dir, "checkout", "main")
	writeFileCS(t, dir, "new.txt", "new\n")
	gitRunCS(t, dir, "add", ".")
	gitRunCS(t, dir, "commit", "-m", "advance")

	saveTestStack(t, fp, []internal.StackEntry{
		{Name: "child", Base: "main"},
	})

	// Interrupt at restoration
	callCount := 0
	internal.StepHook = func(stage internal.CheckoutStage, idx int) error {
		if stage == internal.StageRestoring {
			callCount++
			if callCount == 1 {
				return fmt.Errorf("injected restoration failure")
			}
		}
		return nil
	}

	opts := internal.CheckoutSyncOpts{
		Feature:     "test-feature",
		FeaturePath: fp,
		RepoDir:     dir,
	}

	err := internal.RunCheckoutSync(opts)
	if err == nil {
		t.Fatal("expected restoration interruption")
	}

	// Continue should retry restoration
	internal.StepHook = nil
	if err := internal.ContinueCheckoutSync(opts); err != nil {
		t.Fatalf("restoration retry failed: %v", err)
	}

	branch := gitRunCS(t, dir, "symbolic-ref", "--short", "HEAD")
	if branch != "main" {
		t.Errorf("should be on main, got %s", branch)
	}
}

// ---------- Test: final ancestry verification ----------

func TestCheckoutSync_FinalAncestry(t *testing.T) {
	clearStepHook(t)
	dir := setupCheckoutSyncRepo(t)
	fp := setupFeaturePath(t, dir)

	// Create a chain: main -> parent -> child
	createStackBranch(t, dir, "parent", "main", "parent.txt", "parent\n")
	createStackBranch(t, dir, "child", "parent", "child.txt", "child\n")

	// Advance main
	gitRunCS(t, dir, "checkout", "main")
	writeFileCS(t, dir, "new.txt", "new\n")
	gitRunCS(t, dir, "add", ".")
	gitRunCS(t, dir, "commit", "-m", "advance")

	saveTestStack(t, fp, []internal.StackEntry{
		{Name: "parent", Base: "main"},
		{Name: "child", Base: "parent"},
	})

	opts := internal.CheckoutSyncOpts{
		Feature:     "test-feature",
		FeaturePath: fp,
		RepoDir:     dir,
	}

	if err := internal.RunCheckoutSync(opts); err != nil {
		t.Fatalf("sync failed: %v", err)
	}

	// Verify full chain ancestry
	mainSHA := gitSHA(t, dir, "main")
	parentSHA := gitSHA(t, dir, "parent")

	ok, _ := internal.TestIsAncestor(dir, mainSHA, "parent")
	if !ok {
		t.Error("parent should descend from main")
	}
	ok, _ = internal.TestIsAncestor(dir, parentSHA, "child")
	if !ok {
		t.Error("child should descend from parent")
	}
}

// ---------- Test: push failure propagation ----------

func TestCheckoutSync_PushFailurePropagation(t *testing.T) {
	clearStepHook(t)
	dir := setupCheckoutSyncRepo(t)
	fp := setupFeaturePath(t, dir)

	createStackBranch(t, dir, "child", "main", "child.txt", "child\n")
	gitRunCS(t, dir, "checkout", "main")

	saveTestStack(t, fp, []internal.StackEntry{
		{Name: "child", Base: "main"},
	})

	opts := internal.CheckoutSyncOpts{
		Feature:     "test-feature",
		FeaturePath: fp,
		RepoDir:     dir,
		Push:        true, // no remote configured - will fail
	}

	err := internal.RunCheckoutSync(opts)
	if err == nil {
		t.Fatal("push should fail (no remote)")
	}
	if !strings.Contains(err.Error(), "push") {
		t.Errorf("error should mention push: %v", err)
	}

	// Transaction should be retained for retry
	if !internal.HasCheckoutTransaction(fp) {
		t.Error("transaction should be retained after push failure")
	}

	// Cleanup
	internal.DeleteCheckoutTransaction(fp)
	internal.ReleaseCheckoutLock(fp)
}

// ---------- Test: external sync regression (worktree mode unchanged) ----------

func TestCheckoutSync_ExternalSyncUnchanged(t *testing.T) {
	clearStepHook(t)
	repo := setupGitRepo(t, "master")
	withWorkspaceEnv(t, repo)

	if err := createWorktree("external-feature", "parent", "master", repo, false); err != nil {
		t.Fatal(err)
	}
	parentPath := internal.WorktreePath("external-feature", "parent")
	writeAndCommit(t, parentPath, "parent.txt", "parent-v1\n", "parent v1")

	if err := createWorktree("external-feature", "child", "parent", repo, false); err != nil {
		t.Fatal(err)
	}
	childPath := internal.WorktreePath("external-feature", "child")
	writeAndCommit(t, childPath, "child.txt", "child\n", "child")

	writeAndCommit(t, parentPath, "parent.txt", "parent-v2\n", "parent v2")
	parentHead := gitOutput(t, parentPath, "rev-parse", "parent")

	externalPath := internal.FeaturePath("external-feature")
	result := syncFeature("external-feature", externalSyncLayout{FeaturePath: externalPath, WorktreesRoot: filepath.Join(externalPath, "worktrees")}, false)
	if !result.Complete {
		t.Fatalf("external sync incomplete: %+v", result)
	}
	if internal.RunSilentDir(childPath, "git", "merge-base", "--is-ancestor", parentHead, "child") != nil {
		t.Fatal("external child does not contain updated parent")
	}
}

package cli

import (
	"archive/tar"
	"compress/gzip"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
	"github.com/spf13/cobra"
)

func importCmd() *cobra.Command {
	var fromRepo string

	cmd := &cobra.Command{
		Use:   "import [file]",
		Short: "Import workspace from YAML or tarball",
		Long: `Recreate a workspace from an exported YAML or tarball.

  tws import auth-workspace.yaml           # from YAML file
  tws import auth-workspace.tar.gz         # from tarball (includes inject files)
  tws import --from-repo auth              # from .tws/workspaces/auth.yaml`,
		Args: cobra.MaximumNArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			internal.RequireTool("git")

			ws, err := internal.RequireWorkspace()
			if err != nil {
				return err
			}

			if fromRepo != "" {
				return importFromRepoE(fromRepo, ws)
			}

			if len(args) == 0 {
				return fmt.Errorf("usage: tws import <file> or tws import --from-repo <feature>")
			}

			file := args[0]
			if strings.HasSuffix(file, ".tar.gz") || strings.HasSuffix(file, ".tgz") {
				return importTarballE(file, ws)
			}
			return importYAMLE(file, ws)
		},
	}

	cmd.Flags().StringVar(&fromRepo, "from-repo", "", "Import from .tws/workspaces/<feature>.yaml")

	return cmd
}

func importFromRepoE(feature string, ws internal.Workspace) error {
	repoRoot, err := internal.MainRepoRoot()
	if err != nil {
		return fmt.Errorf("not inside a git repository")
	}

	path := filepath.Join(repoRoot, ".tws", "workspaces", feature+".yaml")
	return importYAMLE(path, ws)
}

func importYAMLE(file string, ws internal.Workspace) error {
	data, err := os.ReadFile(file)
	if err != nil {
		return fmt.Errorf("reading %s: %w", file, err)
	}

	export, err := internal.UnmarshalExport(data)
	if err != nil {
		return fmt.Errorf("parsing %s: %w", file, err)
	}

	return recreateWorkspaceE(export, "", ws)
}

func importTarballE(file string, ws internal.Workspace) error {
	f, err := os.Open(file)
	if err != nil {
		return fmt.Errorf("opening %s: %w", file, err)
	}
	defer f.Close() //nolint:errcheck

	gr, err := gzip.NewReader(f)
	if err != nil {
		return fmt.Errorf("not a valid gzip file: %w", err)
	}
	defer gr.Close() //nolint:errcheck

	tmpDir, err := os.MkdirTemp("", "tws-import-*")
	if err != nil {
		return err
	}
	defer os.RemoveAll(tmpDir) //nolint:errcheck

	tr := tar.NewReader(gr)
	for {
		header, err := tr.Next()
		if err == io.EOF {
			break
		}
		if err != nil {
			return fmt.Errorf("reading tarball: %w", err)
		}

		if isRuntimeState(header.Name) {
			continue
		}
		target, err := safeArchiveTarget(tmpDir, header.Name)
		if err != nil {
			return err
		}
		switch header.Typeflag {
		case tar.TypeDir:
			if err := os.MkdirAll(target, 0755); err != nil {
				return fmt.Errorf("creating archive directory %s: %w", header.Name, err)
			}
		case tar.TypeReg:
			if err := os.MkdirAll(filepath.Dir(target), 0755); err != nil {
				return fmt.Errorf("creating parent for %s: %w", header.Name, err)
			}
			outFile, err := os.OpenFile(target, os.O_CREATE|os.O_WRONLY|os.O_TRUNC, 0600)
			if err != nil {
				return fmt.Errorf("creating extracted file %s: %w", header.Name, err)
			}
			if _, copyErr := io.Copy(outFile, tr); copyErr != nil {
				_ = outFile.Close()
				return fmt.Errorf("extracting %s: %w", header.Name, copyErr)
			}
			if err := outFile.Close(); err != nil {
				return fmt.Errorf("closing extracted file %s: %w", header.Name, err)
			}
		default:
			return fmt.Errorf("unsupported archive entry %q (type %d)", header.Name, header.Typeflag)
		}
	}

	data, err := os.ReadFile(filepath.Join(tmpDir, "workspace.yaml"))
	if err != nil {
		return fmt.Errorf("tarball missing workspace.yaml")
	}

	export, err := internal.UnmarshalExport(data)
	if err != nil {
		return fmt.Errorf("parsing workspace.yaml: %w", err)
	}

	injectSrc := filepath.Join(tmpDir, "inject")
	return recreateWorkspaceE(export, injectSrc, ws)
}

func safeArchiveTarget(root, name string) (string, error) {
	if name == "" || filepath.IsAbs(name) {
		return "", fmt.Errorf("unsafe archive path %q", name)
	}
	clean := filepath.Clean(filepath.FromSlash(name))
	if clean == "." || clean == ".." || strings.HasPrefix(clean, ".."+string(filepath.Separator)) {
		return "", fmt.Errorf("unsafe archive path %q", name)
	}
	root = filepath.Clean(root)
	target := filepath.Join(root, clean)
	rel, err := filepath.Rel(root, target)
	if err != nil || rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) {
		return "", fmt.Errorf("archive path escapes destination: %q", name)
	}
	return target, nil
}

// isRuntimeState returns true for explicit runtime-state paths.
//
// The list is exact-name only: no prefix matching, so no user file is filtered
// accidentally. Any future runtime-state file MUST be added here explicitly.
func isRuntimeState(path string) bool {
	normalized := filepath.ToSlash(path)
	return strings.HasPrefix(normalized, ".tws/state/") ||
		normalized == ".tws/state" ||
		normalized == ".sync-state.yaml" ||
		normalized == ".sync-state.v2.yaml" ||
		normalized == ".sync-run.lock"
}

func recreateWorkspaceE(export internal.WorkspaceExport, injectSrc string, ws internal.Workspace) error {
	if ws.Mode == internal.ModeCheckout {
		return recreateCheckout(export, injectSrc, ws)
	}
	return recreateExternal(export, injectSrc)
}

// recreateCheckout imports into checkout mode: restores under .tws/features/,
// creates/registers branches without linked worktrees, never imports runtime state.
func recreateCheckout(export internal.WorkspaceExport, injectSrc string, ws internal.Workspace) error {
	feature := export.Feature
	if err := internal.GuardFeatureName(ws.MetadataRoot, feature); err != nil {
		return err
	}

	featurePath := ws.FeaturePath(feature)

	if err := os.MkdirAll(featurePath, 0755); err != nil {
		return fmt.Errorf("creating feature directory: %w", err)
	}

	// FEATURE.md
	featureMD := filepath.Join(featurePath, "FEATURE.md")
	if _, err := os.Stat(featureMD); os.IsNotExist(err) {
		_ = os.WriteFile(featureMD, []byte("# "+feature+"\n"), 0644)
	}

	// Stack
	if len(export.Stack.Branches) > 0 {
		if err := internal.SaveStack(featurePath, export.Stack); err != nil {
			return fmt.Errorf("writing stack.yaml: %w", err)
		}
		fmt.Printf("  Restored stack.yaml (%d branches)\n", len(export.Stack.Branches))
	}

	// Decisions
	if len(export.Decisions.Entries) > 0 {
		if err := internal.SaveDecisions(featurePath, export.Decisions); err != nil {
			fmt.Printf("Warning: could not write decisions.yaml: %v\n", err)
		} else {
			fmt.Printf("  Restored decisions.yaml (%d entries)\n", len(export.Decisions.Entries))
		}
	}

	// Inject files
	injectDir := internal.InjectPath(featurePath)
	if err := os.MkdirAll(injectDir, 0755); err != nil {
		return fmt.Errorf("creating inject directory: %w", err)
	}
	if injectSrc != "" {
		if _, err := os.Stat(injectSrc); err == nil {
			count, _ := copyDir(injectSrc, injectDir)
			if count > 0 {
				fmt.Printf("  Restored %d inject file(s)\n", count)
			}
		}
	}

	// Register branches (no worktrees in checkout mode)
	for _, entry := range export.Stack.Branches {
		gitBranch := entry.GitBranch()
		if internal.VerifyGitRef(ws.RepoRoot, gitBranch) == nil {
			fmt.Printf("  [=] %s (branch exists: %s)\n", entry.Name, gitBranch)
		} else {
			fmt.Printf("  [-] %s (branch %s not found — fetch from remote first)\n", entry.Name, gitBranch)
		}
	}

	fmt.Printf("Imported feature: %s (checkout mode — no worktrees created)\n", feature)
	return nil
}

// recreateExternal imports into external mode (original behavior).
func recreateExternal(export internal.WorkspaceExport, injectSrc string) error {
	feature := export.Feature
	wsRoot := internal.TwsRoot()
	if err := internal.GuardFeatureName(wsRoot, feature); err != nil {
		return err
	}

	featurePath := internal.FeaturePath(feature)

	if err := internal.EnsureExternalWorkspaceMarker(wsRoot); err != nil {
		return err
	}
	os.MkdirAll(filepath.Join(featurePath, "worktrees"), 0755) //nolint:errcheck

	if _, err := os.Stat(filepath.Join(featurePath, "FEATURE.md")); os.IsNotExist(err) {
		os.WriteFile(filepath.Join(featurePath, "FEATURE.md"), []byte("# "+feature+"\n"), 0644) //nolint:errcheck
	}

	if len(export.Stack.Branches) > 0 {
		if err := internal.SaveStack(featurePath, export.Stack); err != nil {
			fmt.Printf("Warning: could not write stack.yaml: %v\n", err)
		} else {
			fmt.Printf("  Restored stack.yaml (%d branches)\n", len(export.Stack.Branches))
		}
	}

	if len(export.Decisions.Entries) > 0 {
		if err := internal.SaveDecisions(featurePath, export.Decisions); err != nil {
			fmt.Printf("Warning: could not write decisions.yaml: %v\n", err)
		} else {
			fmt.Printf("  Restored decisions.yaml (%d entries)\n", len(export.Decisions.Entries))
		}
	}

	injectDir := internal.InjectPath(featurePath)
	os.MkdirAll(injectDir, 0755) //nolint:errcheck
	if injectSrc != "" {
		if _, err := os.Stat(injectSrc); err == nil {
			count, _ := copyDir(injectSrc, injectDir)
			if count > 0 {
				fmt.Printf("  Restored %d inject file(s)\n", count)
			}
		}
	}

	for _, entry := range export.Stack.Branches {
		path := internal.WorktreePath(feature, entry.Name)
		if _, err := os.Stat(path); err == nil {
			fmt.Printf("  [=] %s (already exists)\n", entry.Name)
			continue
		}

		if internal.BranchExists(entry.Name) {
			err := internal.RunSilent("git", "worktree", "add", "--force", path, entry.Name)
			if err != nil {
				fmt.Printf("  [x] %s (checkout failed)\n", entry.Name)
			} else {
				fmt.Printf("  [+] %s (checked out)\n", entry.Name)
			}
		} else {
			fmt.Printf("  [-] %s (branch not found — fetch from remote first)\n", entry.Name)
		}
	}

	target := internal.ResolveInjectInto("")
	count, _ := internal.InjectFilesForFeature(featurePath, target)
	if count > 0 {
		fmt.Printf("  Injected files into %d worktree(s)\n", count)
	}

	fmt.Printf("Imported feature: %s\n", feature)
	return nil
}

package cli

import (
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
	"github.com/spf13/cobra"
)

func newCmd() *cobra.Command {
	var base string
	var force bool
	var repo string

	cmd := &cobra.Command{
		Use:   "new <feature> <branch>",
		Short: "Create a worktree branch",
		Args:  cobra.ExactArgs(2),
		ValidArgsFunction: func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
			switch len(args) {
			case 0:
				return internal.ListFeatures(), cobra.ShellCompDirectiveNoFileComp
			case 1:
				return internal.ListBranches(args[0]), cobra.ShellCompDirectiveNoFileComp
			default:
				return nil, cobra.ShellCompDirectiveNoFileComp
			}
		},
		RunE: func(cmd *cobra.Command, args []string) error {
			ws, err := internal.RequireWorkspace()
			if err != nil {
				return err
			}
			if ws.Mode == internal.ModeCheckout {
				if repo != "" {
					return fmt.Errorf("--repo is not supported in checkout mode; checkout workspaces use exactly one repository")
				}
				return createCheckoutBranch(ws, args[0], args[1], base, force)
			}
			return createWorktree(args[0], args[1], base, repo, force)
		},
	}

	cmd.Flags().StringVar(&base, "base", "", "Parent branch, tag, or commit (default: selected repo's origin/HEAD)")
	cmd.Flags().BoolVarP(&force, "force", "f", false, "Force checkout of already checked-out branch")
	cmd.Flags().StringVar(&repo, "repo", "", "Source repository path (for cross-repo worktrees)")

	return cmd
}

// createCheckoutBranch creates a git branch for checkout mode (no worktree).
// Atomic: if metadata persistence fails after branch creation, the branch is
// rolled back (only if this operation created it). Archived entries are
// reactivated. Mismatched existing entries are rejected.
func createCheckoutBranch(ws internal.Workspace, feature, name, requestedBase string, force bool) error {
	if err := internal.GuardFeatureName(ws.MetadataRoot, feature); err != nil {
		return err
	}

	featurePath, err := ws.ResolveFeaturePath(feature)
	if err != nil {
		return err
	}

	// Pre-validate feature directory exists.
	if _, err := os.Stat(featurePath); os.IsNotExist(err) {
		return fmt.Errorf("feature %q not found; run 'tws add %s' first", feature, feature)
	}

	stack, _ := internal.LoadStack(featurePath)

	repoRoot := ws.RepoRoot

	baseName, baseRef, err := resolveCreationBase(repoRoot, "", stack, requestedBase)
	if err != nil {
		return err
	}

	cfg := internal.LoadConfig()
	gitBranch := name
	if cfg.BranchPrefix != "" {
		gitBranch = cfg.BranchPrefix + name
	}

	branchExisted := internal.VerifyGitRef(repoRoot, gitBranch) == nil
	if !branchExisted && gitBranch != name && internal.VerifyGitRef(repoRoot, name) == nil {
		gitBranch = name
		branchExisted = true
	}

	// Check for existing stack entry.
	existing := internal.GetBranch(stack, name)
	if existing.Name != "" {
		// If archived, reactivate.
		if existing.Archived {
			for i := range stack.Branches {
				if stack.Branches[i].Name == name {
					stack.Branches[i].Archived = false
					break
				}
			}
			if err := internal.SaveStack(featurePath, stack); err != nil {
				return fmt.Errorf("failed to unarchive branch: %w", err)
			}
			fmt.Printf("Reactivated archived branch: %s (git: %s)\n", name, existing.GitBranch())
			return nil
		}
		// Existing non-archived entry: validate consistency.
		expectedBranch := gitBranch
		if existing.Branch != "" {
			expectedBranch = existing.Branch
		}
		if existing.GitBranch() != expectedBranch && existing.GitBranch() != gitBranch {
			return fmt.Errorf("branch %q already registered with git branch %q (expected %q); use rename or delete first",
				name, existing.GitBranch(), gitBranch)
		}
		fmt.Printf("Branch %s already registered (git: %s)\n", name, existing.GitBranch())
		return nil
	}

	// Create git branch if it does not exist.
	if !branchExisted {
		if err := internal.RunDir(repoRoot, "git", "branch", gitBranch, baseRef); err != nil {
			return fmt.Errorf("creating git branch %s: %w", gitBranch, err)
		}
	}

	// Register in stack.
	entry := internal.StackEntry{
		Name: name,
		Base: baseName,
	}
	if gitBranch != name {
		entry.Branch = gitBranch
	}
	stack.Branches = append(stack.Branches, entry)

	if err := internal.SaveStack(featurePath, stack); err != nil {
		// Rollback: only delete branch if we created it.
		if !branchExisted {
			_ = internal.RunSilentDir(repoRoot, "git", "branch", "-d", gitBranch)
		}
		return fmt.Errorf("failed to persist stack (branch rolled back): %w", err)
	}

	fmt.Printf("Branch created: %s (git: %s, base: %s)\n", name, gitBranch, baseName)
	return nil
}

// openCheckoutTmux opens a tmux session for a checkout-mode branch.
func openCheckoutTmux(ws internal.Workspace, feature, branch string) {
	session := sanitizeSessionName(feature + "/" + branch)
	fmt.Printf("Checkout branch: use 'git checkout %s' then 'tmux new-session -s %s'\n", branch, session)
}

// createWorktree is the shared logic for creating a worktree branch (external mode).
// Used by both tws new and tws add -n. Explicit base refs are literal;
// an omitted base resolves from the selected repository's origin/HEAD.
func createWorktree(feature, name, requestedBase, repoPath string, force bool) error {
	wsRoot := internal.TwsRoot()
	if err := internal.GuardFeatureName(wsRoot, feature); err != nil {
		return err
	}

	featurePath := internal.FeaturePath(feature)
	path := internal.WorktreePath(feature, name)

	if err := internal.EnsureExternalWorkspaceMarker(wsRoot); err != nil {
		return err
	}
	if err := os.MkdirAll(featurePath, 0755); err != nil {
		return err
	}

	stack, _ := internal.LoadStack(featurePath)
	repoRoot, storedRepo, err := resolveSourceRepo(featurePath, stack, repoPath)
	if err != nil {
		return err
	}

	baseName, baseRef, err := resolveCreationBase(repoRoot, storedRepo, stack, requestedBase)
	if err != nil {
		return err
	}

	cfg := internal.LoadConfig()
	gitBranch := name
	if cfg.BranchPrefix != "" {
		gitBranch = cfg.BranchPrefix + name
	}

	branchExists := internal.VerifyGitRef(repoRoot, gitBranch) == nil
	if !branchExists && gitBranch != name && internal.VerifyGitRef(repoRoot, name) == nil {
		gitBranch = name
		branchExists = true
	}

	if branchExists {
		if isCheckedOutIn(repoRoot, gitBranch) && !force {
			return fmt.Errorf("branch %q is already checked out in another worktree; use --force to check it out anyway", gitBranch)
		}

		gitArgs := []string{"worktree", "add"}
		if force {
			gitArgs = append(gitArgs, "--force")
		}
		gitArgs = append(gitArgs, path, gitBranch)
		if err := internal.RunDir(repoRoot, "git", gitArgs...); err != nil {
			return err
		}
	} else {
		if err := internal.RunDir(repoRoot, "git", "worktree", "add", path, "-b", gitBranch, baseRef); err != nil {
			return err
		}
	}

	if !internal.HasBranch(stack, name) {
		entry := internal.StackEntry{
			Name: name,
			Base: baseName,
			Repo: storedRepo,
		}
		if gitBranch != name {
			entry.Branch = gitBranch
		}
		stack.Branches = append(stack.Branches, entry)
		if err := internal.SaveStack(featurePath, stack); err != nil {
			return err
		}
	}

	target := internal.ResolveInjectInto("")
	if err := internal.InjectFiles(featurePath, path, target); err != nil {
		fmt.Printf("Warning: inject failed: %v\n", err)
	}

	if cfg.AutoHooks != nil && *cfg.AutoHooks {
		if err := installHooksForWorktree(path, feature); err != nil {
			fmt.Printf("Warning: auto-hooks install failed: %v\n", err)
		}
	}

	if storedRepo != "" {
		fmt.Printf("Worktree created: %s (base: %s, repo: %s)\n", path, baseName, storedRepo)
	} else {
		fmt.Printf("Worktree created: %s (base: %s)\n", path, baseName)
	}
	return nil
}

func resolveSourceRepo(featurePath string, stack internal.Stack, requestedRepo string) (string, string, error) {
	if requestedRepo != "" {
		absRepo, err := internal.AbsPath(requestedRepo)
		if err != nil {
			return "", "", fmt.Errorf("invalid repo path %s: %w", requestedRepo, err)
		}
		repoRoot, err := internal.GitRepoRootIn(absRepo)
		if err != nil {
			return "", "", fmt.Errorf("%s is not a Git repository", requestedRepo)
		}
		return repoRoot, repoRoot, nil
	}

	if repoRoot, err := internal.MainRepoRoot(); err == nil {
		return repoRoot, "", nil
	}

	type candidate struct {
		root       string
		storedRepo string
	}
	candidates := make(map[string]candidate)
	for _, entry := range stack.Branches {
		if entry.Repo != "" {
			root, err := internal.GitRepoRootIn(entry.Repo)
			if err == nil {
				candidates[root] = candidate{root: root, storedRepo: root}
			}
			continue
		}

		worktreePath := filepath.Join(featurePath, "worktrees", entry.Name)
		if _, err := os.Stat(worktreePath); err != nil {
			continue
		}
		root, err := internal.MainRepoRootIn(worktreePath)
		if err == nil {
			candidates[root] = candidate{root: root}
		}
	}

	if len(candidates) == 1 {
		for _, c := range candidates {
			return c.root, c.storedRepo, nil
		}
	}
	if len(candidates) > 1 {
		return "", "", fmt.Errorf("feature uses multiple repositories; specify --repo")
	}
	return "", "", fmt.Errorf("could not infer source repository; run from a Git repo or specify --repo")
}

func resolveCreationBase(repoRoot, storedRepo string, stack internal.Stack, requestedBase string) (string, string, error) {
	if requestedBase == "" {
		baseName, err := internal.DefaultBranchIn(repoRoot)
		if err != nil {
			return "", "", err
		}
		remoteRef := "origin/" + baseName
		if internal.VerifyGitRef(repoRoot, remoteRef) == nil {
			return baseName, remoteRef, nil
		}
		if internal.VerifyGitRef(repoRoot, baseName) == nil {
			return baseName, baseName, nil
		}
		return "", "", fmt.Errorf("default branch %q does not exist in %s", baseName, repoRoot)
	}

	baseRef := requestedBase
	if parent := internal.GetBranch(stack, requestedBase); parent.Name != "" {
		if !sameStackRepo(parent.Repo, storedRepo) {
			return "", "", fmt.Errorf("base %q belongs to a different repository", requestedBase)
		}
		baseRef = parent.GitBranch()
	}
	if err := internal.VerifyGitRef(repoRoot, baseRef); err != nil {
		return "", "", fmt.Errorf("base ref %q does not exist in %s", requestedBase, repoRoot)
	}
	return requestedBase, baseRef, nil
}

func sameStackRepo(a, b string) bool {
	return internal.SameStackRepo(a, b)
}

func isCheckedOutIn(repoRoot, branch string) bool {
	out, err := exec.Command("git", "-C", repoRoot, "worktree", "list", "--porcelain").Output()
	if err != nil {
		return false
	}
	for line := range strings.SplitSeq(string(out), "\n") {
		if strings.TrimSpace(line) == "branch refs/heads/"+branch {
			return true
		}
	}
	return false
}

package cli

import (
	"fmt"
	"os"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
	"github.com/spf13/cobra"
)

func pushCmd() *cobra.Command {
	var dryRun bool

	cmd := &cobra.Command{
		Use:   "push <feature>",
		Short: "Push all branches in a feature with --force-with-lease",
		Args:  cobra.ExactArgs(1),
		ValidArgsFunction: func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
			if len(args) == 0 {
				return internal.ListFeatures(), cobra.ShellCompDirectiveNoFileComp
			}
			return nil, cobra.ShellCompDirectiveNoFileComp
		},
		RunE: func(cmd *cobra.Command, args []string) error {
			internal.RequireTool("git")
			feature := args[0]

			ws, err := internal.RequireWorkspace()
			if err != nil {
				return err
			}
			// The sibling-space guard used to arrive through
			// internal.RequireFeaturePath; the external arm no longer calls it,
			// so the command owns the guard explicitly, before any layout work.
			if err := internal.GuardFeatureName(ws.MetadataRoot, feature); err != nil {
				return err
			}
			if ws.Mode == internal.ModeCheckout {
				return pushFeatureCheckout(feature, dryRun)
			}
			layout, err := resolveExternalSyncLayout(ws, internal.TwsRoot(), feature)
			if err != nil {
				return err
			}
			return pushFeature(feature, layout, dryRun)
		},
	}

	cmd.Flags().BoolVar(&dryRun, "dry-run", false, "Show what would be pushed without pushing")

	return cmd
}

// pushFeature pushes every entry of an external feature. It takes the resolved
// layout so the push half of a run can never target a different root than the
// rebase half.
func pushFeature(feature string, layout externalSyncLayout, dryRun bool) error {
	stack, err := internal.LoadStack(layout.FeaturePath)
	if err != nil {
		return fmt.Errorf("no stack.yaml found for feature: %s", feature)
	}
	return pushEntries(layout, stack.Branches, dryRun)
}

// pushScoped is the sync-side push of a new-mode run, for every scope. It is
// strict and payload-aware: it pushes only the entries this run selected AND
// successfully rebased, in selection order, records every success in the
// payload before the next push is attempted, and stops at the first failure so
// `--continue` can retry exactly the entries that were never pushed.
func pushScoped(feature string, layout externalSyncLayout, stack internal.Stack, sel internal.SyncSelection, completed []string, payload *internal.SyncRunState) error {
	if payload == nil {
		return fmt.Errorf("internal error: new-mode push without run state for %s", feature)
	}
	rebased := make(map[string]bool, len(completed))
	for _, name := range completed {
		rebased[name] = true
	}
	alreadyPushed := make(map[string]bool, len(payload.Pushed))
	for _, name := range payload.Pushed {
		alreadyPushed[name] = true
	}

	for _, selected := range sel.Entries {
		if !rebased[selected.Name] || alreadyPushed[selected.Name] {
			continue
		}
		entry := internal.GetBranch(stack, selected.Name)
		if entry.Name == "" {
			continue
		}
		path := layout.WorktreePath(entry.Name)
		if _, err := os.Stat(path); os.IsNotExist(err) {
			// Same skip as the legacy loop: an archived entry has no worktree
			// and is never pushed by tws.
			fmt.Printf("  [-] %s (archived, skipped)\n", entry.Name)
			continue
		}

		repoDir := path
		if entry.Repo != "" {
			repoDir = entry.Repo
		}
		if err := internal.RunDirClean(repoDir, "git", "push", "--force-with-lease", "origin", entry.GitBranch()); err != nil {
			fmt.Printf("  [x] %s (push failed)\n", entry.Name)
			saveScopedPushFailure(layout.FeaturePath, payload, entry.Name)
			return fmt.Errorf("push failed for %s; fix the remote problem, then resume with: tws sync %s --continue", entry.Name, feature)
		}
		fmt.Printf("  [+] %s (pushed)\n", entry.Name)

		// The logical name is recorded only after Git succeeded, and the
		// payload is persisted before the next push is attempted.
		payload.Pushed = append(payload.Pushed, entry.Name)
		if err := internal.SaveSyncRunState(layout.FeaturePath, payload); err != nil {
			return fmt.Errorf("record pushed entry %s: %w", entry.Name, err)
		}
	}
	return nil
}

// pushEntries is the legacy push loop of `tws push` and of every no-flag run:
// it prints per-entry failures and returns nil, which is exactly the
// compatibility behaviour a new-mode run must not have.
func pushEntries(layout externalSyncLayout, entries []internal.StackEntry, dryRun bool) error {
	for _, entry := range entries {
		path := layout.WorktreePath(entry.Name)

		// Skip archived branches
		if _, err := os.Stat(path); os.IsNotExist(err) {
			fmt.Printf("  [-] %s (archived, skipped)\n", entry.Name)
			continue
		}

		if dryRun {
			fmt.Printf("  [~] %s (would push --force-with-lease)\n", entry.Name)
			continue
		}

		// Determine repo context
		repoDir := path
		if entry.Repo != "" {
			repoDir = entry.Repo
		}

		runErr := internal.RunDirClean(repoDir, "git", "push", "--force-with-lease", "origin", entry.GitBranch())
		if runErr != nil {
			fmt.Printf("  [x] %s (push failed)\n", entry.Name)
		} else {
			fmt.Printf("  [+] %s (pushed)\n", entry.Name)
		}
	}
	return nil
}

// pushFeatureCheckout holds the pre-sync-modes push body verbatim. Checkout
// mode keeps failing with ErrWorktreeUnsupported and a nonzero exit; neither
// the layout resolver nor the GitBranch() ref fix reaches it.
func pushFeatureCheckout(feature string, dryRun bool) error {
	featurePath, err := internal.RequireFeaturePath(feature)
	if err != nil {
		return err
	}

	stack, err := internal.LoadStack(featurePath)
	if err != nil {
		return fmt.Errorf("no stack.yaml found for feature: %s", feature)
	}

	for _, entry := range stack.Branches {
		path, err := internal.RequireWorktreePath(feature, entry.Name)
		if err != nil {
			return err
		}

		// Skip archived branches
		if _, err := os.Stat(path); os.IsNotExist(err) {
			fmt.Printf("  [-] %s (archived, skipped)\n", entry.Name)
			continue
		}

		if dryRun {
			fmt.Printf("  [~] %s (would push --force-with-lease)\n", entry.Name)
			continue
		}

		// Determine repo context
		repoDir := path
		if entry.Repo != "" {
			repoDir = entry.Repo
		}

		runErr := internal.RunDirClean(repoDir, "git", "push", "--force-with-lease", "origin", entry.Name)
		if runErr != nil {
			fmt.Printf("  [x] %s (push failed)\n", entry.Name)
		} else {
			fmt.Printf("  [+] %s (pushed)\n", entry.Name)
		}
	}
	return nil
}

package cli

import (
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
)

// ---------------------------------------------------------------------------
// tws push after the layout refactor (§3.11, §7.6, AC 59).
// ---------------------------------------------------------------------------

func runPush(t *testing.T, args ...string) (stdout, stderr string, exit int) {
	t.Helper()
	stdout, stderr = syncCaptureStreams(t, func() {
		exit = syncExecute(pushCmd, args...)
	})
	return stdout, stderr, exit
}

// TestPushLayout_ExternalPushesTheGitBranch pins the C2 fix: the pushed ref is
// entry.GitBranch(), never the logical Name.
func TestPushLayout_ExternalPushesTheGitBranch(t *testing.T) {
	f := newScopedFixture(t)
	gitRun(t, f.wt("child"), "branch", "-m", "child", "user/child")
	stack, err := internal.LoadStack(f.featurePath)
	if err != nil {
		t.Fatal(err)
	}
	for i := range stack.Branches {
		if stack.Branches[i].Name == "child" {
			stack.Branches[i].Branch = "user/child"
		}
	}
	if err := internal.SaveStack(f.featurePath, stack); err != nil {
		t.Fatal(err)
	}

	stdout, stderr, exit := runPush(t, f.feature)
	if exit != 0 {
		t.Fatalf("exit = %d\n%s\n%s", exit, stdout, stderr)
	}
	if !strings.Contains(stdout, "[+] child (pushed)") {
		t.Fatalf("the per-entry line is keyed by the logical Name:\n%s\n%s", stdout, stderr)
	}
	refs := gitOutput(t, f.remote, "for-each-ref", "--format=%(refname)")
	if !strings.Contains(refs, "refs/heads/user/child") {
		t.Fatalf("the pushed ref must be the Git branch:\n%s", refs)
	}
	// Coupled entries are unchanged.
	for _, name := range []string{"root", "parent"} {
		if !strings.Contains(refs, "refs/heads/"+name) {
			t.Fatalf("coupled entry %s must still be pushed:\n%s", name, refs)
		}
	}
}

// TestPushLayout_DryRunIsUnchanged keeps the read-only surface stable.
func TestPushLayout_DryRunIsUnchanged(t *testing.T) {
	f := newScopedFixture(t)
	stdout, stderr, exit := runPush(t, f.feature, "--dry-run")
	if exit != 0 {
		t.Fatalf("exit = %d\n%s\n%s", exit, stdout, stderr)
	}
	for _, name := range []string{"root", "parent", "child"} {
		if !strings.Contains(stdout, "  [~] "+name+" (would push --force-with-lease)") {
			t.Fatalf("missing dry-run line for %s:\n%s", name, stdout)
		}
	}
	refs := gitOutput(t, f.remote, "for-each-ref", "--format=%(refname)")
	if strings.Contains(refs, "refs/heads/root") {
		t.Fatalf("--dry-run must push nothing:\n%s", refs)
	}
}

// TestPushLayout_CheckoutModeStillUnsupported pins that checkout-mode push
// keeps today's ErrWorktreeUnsupported failure and a nonzero exit.
func TestPushLayout_CheckoutModeStillUnsupported(t *testing.T) {
	t.Setenv("GIT_CONFIG_COUNT", "0")
	t.Setenv("GIT_CONFIG_NOSYSTEM", "1")
	dir := setupGitRepoCheckout(t)
	t.Setenv("HOME", dir)
	t.Setenv("TWS_ROOT", "")
	old, _ := os.Getwd()
	t.Cleanup(func() { _ = os.Chdir(old) })
	if err := os.Chdir(dir); err != nil {
		t.Fatal(err)
	}
	ws, err := internal.RequireWorkspace()
	if err != nil {
		t.Fatal(err)
	}
	if ws.Mode != internal.ModeCheckout {
		t.Fatalf("fixture mode = %s, want checkout", ws.Mode)
	}
	featurePath := filepath.Join(ws.MetadataRoot, "features", "auth")
	if err := os.MkdirAll(featurePath, 0o755); err != nil {
		t.Fatal(err)
	}
	if err := internal.SaveStack(featurePath, internal.Stack{Branches: []internal.StackEntry{{Name: "api", Base: "main"}}}); err != nil {
		t.Fatal(err)
	}

	stdout, stderr, exit := runPush(t, "auth")
	if exit == 0 {
		t.Fatalf("checkout push must keep failing:\n%s\n%s", stdout, stderr)
	}
	if !strings.Contains(stderr, "linked worktrees are not supported in checkout mode") {
		t.Fatalf("stderr = %q", stderr)
	}
}

// TestPushLayout_SelectedPushIsOrderedAndFiltered pins the new-mode push: only
// the selected, rebased entries are pushed, in selection order, and every
// success is recorded in the payload.
func TestPushLayout_SelectedPushIsOrderedAndFiltered(t *testing.T) {
	f := newScopedFixture(t)
	stack, err := internal.LoadStack(f.featurePath)
	if err != nil {
		t.Fatal(err)
	}
	policy := internal.SyncRunPolicy{
		Fetch:       internal.SyncFetchDisabled,
		Propagation: internal.SyncPropagationFull,
		ScopeKind:   internal.SyncScopeSubtree,
		Selector:    "parent",
	}
	sel, err := internal.ResolveSyncSelection(stack, policy, internal.SyncSelectionOpts{
		Mode:    internal.ModeExternal,
		NewMode: true,
		Feature: f.feature,
	})
	if err != nil {
		t.Fatal(err)
	}
	payload := internal.NewSyncRunState(f.feature, "tws-scoped-sync-0123456789abcdef0123456789abcdef.lock", "token", policy)
	payload.Selected = sel.SelectedNames()

	stdout, _ := syncCaptureStreams(t, func() {
		if err := pushScoped(f.feature, f.layout, stack, sel, []string{"parent", "child"}, payload); err != nil {
			t.Errorf("pushScoped: %v", err)
		}
	})
	if !strings.Contains(stdout, "[+] parent (pushed)") || !strings.Contains(stdout, "[+] child (pushed)") {
		t.Fatalf("missing per-entry lines:\n%s", stdout)
	}
	if strings.Contains(stdout, "root") {
		t.Fatalf("the new-mode push must push only the selected entries:\n%s", stdout)
	}
	if got := strings.Join(payload.Pushed, ","); got != "parent,child" {
		t.Fatalf("payload pushed = %q, want the selection order parent,child", got)
	}
	refs := gitOutput(t, f.remote, "for-each-ref", "--format=%(refname)")
	if strings.Contains(refs, "refs/heads/root") {
		t.Fatalf("an unselected entry reached the remote:\n%s", refs)
	}
}

// TestPushLayout_ArchivedEntriesAreSkipped keeps the frozen skip line.
func TestPushLayout_ArchivedEntriesAreSkipped(t *testing.T) {
	f := newScopedFixture(t)
	if err := os.RemoveAll(f.wt("child")); err != nil {
		t.Fatal(err)
	}
	stdout, stderr, exit := runPush(t, f.feature)
	if exit != 0 {
		t.Fatalf("exit = %d\n%s\n%s", exit, stdout, stderr)
	}
	if !strings.Contains(stdout, "  [-] child (archived, skipped)") {
		t.Fatalf("missing the archived skip line:\n%s", stdout)
	}
}

package cli

import (
	"fmt"
	"os"
	"sort"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
	"github.com/spf13/cobra"
)

func syncCmd() *cobra.Command {
	var verbose bool
	var push bool
	var cont bool
	var abort bool
	var testCmd string
	var doFetch bool
	var noFetch bool
	var full bool
	var localOnly bool
	var only string
	var from string

	cmd := &cobra.Command{
		Use:   "sync <feature>",
		Short: "Rebase branches in dependency order",
		Args:  cobra.ExactArgs(1),
		ValidArgsFunction: func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
			if len(args) == 0 {
				return internal.ListFeatures(), cobra.ShellCompDirectiveNoFileComp
			}
			return nil, cobra.ShellCompDirectiveNoFileComp
		},
		RunE: func(cmd *cobra.Command, args []string) error {
			internal.RequireTool("git")

			ws, err := internal.RequireWorkspace()
			if err != nil {
				return err
			}

			// Pure command-line checks (I1-I8) run before mode dispatch so both
			// modes reject identically and identically early.
			policy, newMode, changed, err := resolveSyncPolicy(cmd, ws.Mode)
			if err != nil {
				return err
			}

			if ws.Mode == internal.ModeCheckout {
				return runCheckoutSync(ws, internal.CheckoutSyncOpts{
					Feature:     args[0],
					Push:        push,
					TestCommand: testCmd,
					Verbose:     verbose,
					Policy:      policy,
					NewMode:     newMode,
					Continue:    cont,
					Abort:       abort,
					Changed:     changed,
				})
			}

			feature := args[0]
			// One guard covers the plain, --abort, and --continue paths.
			// syncFeature carries none: it has no error channel and would
			// degrade the message to "sync incomplete".
			twsRoot := internal.TwsRoot()
			if err := internal.GuardFeatureName(twsRoot, feature); err != nil {
				return err
			}
			layout, layoutErr := resolveExternalSyncLayout(ws, twsRoot, feature)
			if layoutErr != nil {
				return layoutErr
			}

			state, stateErr := classifySyncState(layout.FeaturePath, newMode)
			if stateErr != nil {
				return stateErr
			}
			// Deferred I7: cont && abort survived the command-line block, so no
			// trigger flag was supplied. Refuse only against new-mode state.
			if cont && abort && (state.Marker != "" || state.Payload != nil) {
				return errSyncContinueAbort()
			}

			if abort {
				if err := syncCellRefusal(syncVerbAbort, feature, layout, state); err != nil {
					return err
				}
				return handleSyncAbortCell(feature, layout, state)
			}
			if cont {
				if err := syncCellRefusal(syncVerbContinue, feature, layout, state); err != nil {
					return err
				}
				if newMode && (state.Cell == 1 || state.Cell == 7) {
					return fmt.Errorf("%s", errSyncModeFlagsNeedV2)
				}
				if state.Cell == 5 {
					return handleScopedSyncContinue(feature, layout, ws, push, policy, changed, state)
				}
				return handleSyncContinue(feature, layout, push)
			}
			if err := syncCellRefusal(syncVerbPlain, feature, layout, state); err != nil {
				return err
			}
			if internal.HasSyncState(layout.FeaturePath) {
				legacy, _ := internal.LoadSyncState(layout.FeaturePath)
				return fmt.Errorf("previous sync incomplete (failed on: %s); use --continue or --abort", legacy.FailedBranch)
			}

			if newMode {
				return runScopedSync(feature, layout, ws, policy, push, verbose)
			}

			result := syncFeature(feature, layout, verbose)
			if !result.Complete {
				return fmt.Errorf("sync incomplete")
			}
			fmt.Println("Sync complete.")
			if push {
				fmt.Println("\nPushing...")
				if err := pushFeature(feature, layout, false); err != nil {
					return err
				}
			}
			return nil
		},
	}

	cmd.Flags().BoolVarP(&verbose, "verbose", "v", false, "Show full git fetch output")
	cmd.Flags().BoolVar(&push, "push", false, "Push all branches after syncing")
	cmd.Flags().BoolVar(&cont, "continue", false, "Resume after conflict resolution")
	cmd.Flags().BoolVar(&abort, "abort", false, "Discard sync state and start fresh")
	cmd.Flags().StringVar(&testCmd, "test", "", "Validation command to run after each rebase (checkout mode)")
	cmd.Flags().BoolVar(&doFetch, "fetch", false, "Fetch before planning (external default)")
	cmd.Flags().BoolVar(&noFetch, "no-fetch", false, "Plan and rebase from local refs only; no automatic network input (checkout default)")
	cmd.Flags().BoolVar(&full, "full", false, "Advance anchors onto their configured base (default)")
	cmd.Flags().BoolVar(&localOnly, "local-only", false, "Replay local parent tips into children; never advance an anchor")
	cmd.Flags().StringVar(&only, "only", "", "Sync exactly one stack entry by its logical name")
	cmd.Flags().StringVar(&from, "from", "", "Sync one stack entry and its descendant closure, by logical name")

	_ = cmd.RegisterFlagCompletionFunc("only", syncEntryCompletion)
	_ = cmd.RegisterFlagCompletionFunc("from", syncEntryCompletion)

	return cmd
}

// runScopedSync executes §3.6 steps 10-17 of a new-mode external run.
func runScopedSync(feature string, layout externalSyncLayout, ws internal.Workspace, policy internal.SyncRunPolicy, push, verbose bool) error {
	stack, err := internal.LoadStack(layout.FeaturePath)
	if err != nil {
		return fmt.Errorf("sync modes require a stack; feature %q has no readable stack.yaml", feature)
	}
	sel, err := internal.ResolveSyncSelection(stack, policy, internal.SyncSelectionOpts{
		Mode:    ws.Mode,
		NewMode: true,
		Feature: feature,
	})
	if err != nil {
		return err
	}
	if err := verifySelectedBasesLocally(layout, stack, sel); err != nil {
		return err
	}

	marker, err := syncMarkerFn()
	if err != nil {
		return err
	}
	if err := syncMarkerCollision(stack, marker); err != nil {
		return err
	}
	token, err := newSyncOwnerToken()
	if err != nil {
		return err
	}

	testCommand := internal.LoadConfig().TestCommand
	validationSource := "none"
	if testCommand != "" {
		validationSource = "config"
	}

	payload, err := setupSyncRunState(layout, feature, marker, token, sel, push, testCommand, validationSource)
	if err != nil {
		return err
	}

	printSyncModeHeader(policy)

	run := &syncRunContext{Policy: policy, Sel: sel, Payload: payload}
	result := syncFeatureScoped(feature, layout, verbose, stack, run)
	if !result.Complete {
		return fmt.Errorf("sync incomplete")
	}
	fmt.Println("Sync complete.")
	if push {
		// The payload, the sentinel, and the guard stay on disk when a scoped
		// push fails, so --continue can retry exactly the entries that were
		// never pushed.
		if err := runNewModePush(feature, layout, stack, sel, result.Completed, payload); err != nil {
			return err
		}
	}
	return finalizeScopedSyncRun(layout, payload)
}

// runNewModePush is the §7.6 push half of a new-mode run. A `scope=all` run
// keeps the legacy whole-feature push, so "`--push` pushes the feature" is
// unchanged when nothing was scoped: every materialized entry is considered —
// including an anchor a local-only run deliberately did not rebase — and the
// legacy lenient per-entry behaviour is preserved. `only` and `subtree` scopes
// use the strict, payload-aware, resumable push.
func runNewModePush(feature string, layout externalSyncLayout, stack internal.Stack, sel internal.SyncSelection, completed []string, payload *internal.SyncRunState) error {
	fmt.Println("\nPushing...")
	payload.Stage = internal.SyncStagePushing
	if err := internal.SaveSyncRunState(layout.FeaturePath, payload); err != nil {
		return fmt.Errorf("record push stage: %w", err)
	}
	if sel.Policy.ScopeKind == internal.SyncScopeAll {
		return pushFeature(feature, layout, false)
	}
	return pushScoped(feature, layout, stack, sel, completed, payload)
}

// finalizeScopedSyncRun records the finalizing stage immediately before
// teardown — never earlier — and then tears the run's state down. A teardown
// error is propagated verbatim: no later artifact is cleared behind it.
func finalizeScopedSyncRun(layout externalSyncLayout, payload *internal.SyncRunState) error {
	payload.Stage = internal.SyncStageFinalizing
	if err := internal.SaveSyncRunState(layout.FeaturePath, payload); err != nil {
		return fmt.Errorf("record finalizing stage: %w", err)
	}
	return clearSyncRunState(layout.FeaturePath, true)
}

// verifySelectedBasesLocally is the I14 no-fetch preflight. It probes only the
// base refs the selected plan will actually use.
func verifySelectedBasesLocally(layout externalSyncLayout, stack internal.Stack, sel internal.SyncSelection) error {
	if sel.Policy.Fetch != internal.SyncFetchDisabled {
		return nil
	}
	for _, entry := range sel.Entries {
		if entry.Role == internal.SyncRoleAnchor && sel.Policy.Propagation == internal.SyncPropagationLocalOnly {
			continue
		}
		real := internal.GetBranch(stack, entry.Name)
		repoCtx := syncRepoContext(layout, real)
		ref := resolveEntryBase(stack, real, repoCtx)
		if ref == "" {
			continue
		}
		if err := internal.VerifyGitRef(repoCtx, ref); err != nil {
			return fmt.Errorf("base %q for stack entry %q does not resolve locally; drop --no-fetch or fetch manually first", ref, entry.Name)
		}
	}
	return nil
}

func handleSyncAbortCell(feature string, layout externalSyncLayout, state internal.SyncExternalState) error {
	if state.GuardForeign() {
		return fmt.Errorf("sync guard %s does not belong to the recorded scoped run; inspect it and remove it manually", state.GuardPath)
	}
	switch state.Cell {
	case 2, 5:
		if state.Payload != nil && state.Payload.FailedBranch != "" {
			path := layout.WorktreePath(state.Payload.FailedBranch)
			if isRebaseInProgress(path) {
				_ = internal.RunSilentDir(path, "git", "rebase", "--abort")
			}
		}
		internal.DeleteSyncRunState(layout.FeaturePath)
		if state.Cell == 5 {
			internal.DeleteSyncState(layout.FeaturePath)
		}
		internal.ReleaseSyncRunGuard(layout.FeaturePath)
		fmt.Println("Sync state cleared.")
		return nil
	case 4:
		if internal.HasSyncRunState(layout.FeaturePath) {
			return fmt.Errorf("scoped sync state appeared at %s while aborting; re-run: tws sync %s --abort",
				internal.SyncRunStatePath(layout.FeaturePath), feature)
		}
		internal.DeleteSyncState(layout.FeaturePath)
		internal.ReleaseSyncRunGuard(layout.FeaturePath)
		fmt.Println("Sync state cleared.")
		return nil
	}
	return handleSyncAbort(feature, layout)
}

func handleSyncAbort(feature string, layout externalSyncLayout) error {
	state, err := internal.LoadSyncState(layout.FeaturePath)
	if err != nil {
		fmt.Println("Nothing to abort — no sync in progress.")
		return nil
	}
	if state.FailedBranch != "" {
		path := layout.WorktreePath(state.FailedBranch)
		if isRebaseInProgress(path) {
			_ = internal.RunSilentDir(path, "git", "rebase", "--abort")
		}
	}
	internal.DeleteSyncState(layout.FeaturePath)
	fmt.Println("Sync state cleared.")
	return nil
}

func handleSyncContinue(feature string, layout externalSyncLayout, push bool) error {
	state, err := internal.LoadSyncState(layout.FeaturePath)
	if err != nil {
		return fmt.Errorf("nothing to continue — no sync in progress")
	}
	failedPath := layout.WorktreePath(state.FailedBranch)
	if state.FailedBranch != "" && isRebaseInProgress(failedPath) {
		return fmt.Errorf("rebase still in progress in %s; resolve conflicts, run git add . && git rebase --continue, then retry", state.FailedBranch)
	}

	stack, err := internal.LoadStack(layout.FeaturePath)
	if err != nil {
		return fmt.Errorf("load stack: %w", err)
	}
	if state.FailedBranch != "" {
		failedEntry := internal.GetBranch(stack, state.FailedBranch)
		if failedEntry.Name == "" {
			return fmt.Errorf("failed branch %q no longer exists in stack", state.FailedBranch)
		}
		if !branchContainsConfiguredParent(layout.WorktreesRoot, stack, failedEntry) {
			return fmt.Errorf("resolved branch %s still does not contain its configured parent %s", failedEntry.Name, failedEntry.Base)
		}
		fmt.Println(formatSyncStatus(state.FailedBranch, "active", "resolved"))
	}

	done := make(map[string]bool)
	for _, name := range state.Completed {
		done[name] = true
	}
	if state.FailedBranch != "" {
		done[state.FailedBranch] = true
	}
	sorted, err := internal.TopoSort(stack)
	if err != nil {
		return err
	}
	fmt.Printf("Resuming sync with %d pending branch(es)\n", len(state.Pending))
	result := syncWithStackFiltered(feature, layout, stack, sorted, done)
	if !result.Complete {
		return fmt.Errorf("sync incomplete")
	}
	fmt.Println("Sync complete.")
	if push {
		fmt.Println("\nPushing...")
		if err := pushFeature(feature, layout, false); err != nil {
			return err
		}
	}
	return nil
}

// handleScopedSyncContinue resumes cell 5 — the only resumable new-mode cell.
func handleScopedSyncContinue(feature string, layout externalSyncLayout, ws internal.Workspace, push bool, policy internal.SyncRunPolicy, changed map[string]bool, state internal.SyncExternalState) error {
	payload := state.Payload
	if payload == nil {
		return fmt.Errorf("nothing to continue — no sync in progress")
	}
	if err := syncContinueMismatches(payload, policy, changed, push); err != nil {
		return err
	}

	failedPath := layout.WorktreePath(payload.FailedBranch)
	if payload.FailedBranch != "" && isRebaseInProgress(failedPath) {
		return fmt.Errorf("rebase still in progress in %s; resolve conflicts, run git add . && git rebase --continue, then retry", payload.FailedBranch)
	}

	stack, err := internal.LoadStack(layout.FeaturePath)
	if err != nil {
		return fmt.Errorf("load stack: %w", err)
	}
	sel, err := scopedSelectionFromPayload(stack, payload, feature, ws.Mode)
	if err != nil {
		return err
	}

	if payload.FailedBranch != "" && !payloadCompleted(payload, payload.FailedBranch) {
		failedEntry := internal.GetBranch(stack, payload.FailedBranch)
		if failedEntry.Name == "" {
			return fmt.Errorf("failed branch %q no longer exists in stack", payload.FailedBranch)
		}
		if !branchContainsConfiguredParent(layout.WorktreesRoot, stack, failedEntry) {
			return fmt.Errorf("resolved branch %s still does not contain its configured parent %s", failedEntry.Name, failedEntry.Base)
		}
		fmt.Println(formatSyncStatus(payload.FailedBranch, "active", "resolved"))
	}

	if state.GuardForeign() {
		return fmt.Errorf("sync guard %s does not belong to the recorded scoped run; inspect it and remove it manually", state.GuardPath)
	}
	if err := internal.ReclaimSyncRunGuard(layout.FeaturePath, payload.OwnerToken); err != nil {
		return err
	}

	done := make(map[string]bool)
	for _, name := range payload.Completed {
		done[name] = true
	}
	if payload.FailedBranch != "" {
		done[payload.FailedBranch] = true
	}
	sorted, err := internal.TopoSort(stack)
	if err != nil {
		return err
	}

	printSyncModeHeader(payload.Policy())
	fmt.Printf("Resuming sync with %d pending branch(es)\n", len(payload.Pending))

	run := &syncRunContext{Policy: payload.Policy(), Sel: sel, Payload: payload}
	result := syncWithStackScoped(feature, layout, stack, sorted, done, run)
	if !result.Complete {
		return fmt.Errorf("sync incomplete")
	}
	fmt.Println("Sync complete.")
	if payload.Push {
		if err := runNewModePush(feature, layout, stack, sel, result.Completed, payload); err != nil {
			return err
		}
	}
	return finalizeScopedSyncRun(layout, payload)
}

// syncContinueMismatches applies §10.5 rules 2, 3, and 5 to an external v2
// resume.
func syncContinueMismatches(payload *internal.SyncRunState, policy internal.SyncRunPolicy, changed map[string]bool, push bool) error {
	if changed["fetch"] || changed["no-fetch"] {
		if policy.Fetch != payload.FetchPolicy {
			return syncContinueMismatch("fetch", string(payload.FetchPolicy), string(policy.Fetch))
		}
	}
	if changed["full"] || changed["local-only"] {
		if policy.Propagation != payload.PropagationPolicy {
			return syncContinueMismatch("propagation", string(payload.PropagationPolicy), string(policy.Propagation))
		}
	}
	if changed["only"] || changed["from"] {
		want := payload.Policy().ScopeLabel()
		if policy.ScopeLabel() != want {
			return syncContinueMismatch("scope", want, policy.ScopeLabel())
		}
	}
	if changed["push"] && push != payload.Push {
		return syncContinueMismatch("push", fmt.Sprintf("%v", payload.Push), fmt.Sprintf("%v", push))
	}
	return nil
}

func syncContinueMismatch(axis, started, requested string) error {
	return fmt.Errorf("cannot change %s on --continue: the run was started with %s=%s and this invocation requests %s", axis, axis, started, requested)
}

// payloadCompleted reports whether an entry already finished its rebase in the
// interrupted run. A push failure records the entry in BOTH `completed` and
// `failed_branch`: its rebase and its validation already succeeded, so the
// resume must neither re-check the parent edge, nor re-run validation, nor
// print `[~] resolved` for it — it goes straight to retrying the entries that
// were never pushed.
func payloadCompleted(payload *internal.SyncRunState, name string) bool {
	for _, done := range payload.Completed {
		if done == name {
			return true
		}
	}
	return false
}

// scopedSelectionFromPayload rebuilds the run's selection from the payload's
// materialized `selected` list, so a stack.yaml edit between failure and
// --continue cannot silently re-scope the run.
func scopedSelectionFromPayload(stack internal.Stack, payload *internal.SyncRunState, feature string, mode internal.WorkspaceMode) (internal.SyncSelection, error) {
	for _, name := range payload.Selected {
		if !internal.HasBranch(stack, name) {
			return internal.SyncSelection{}, fmt.Errorf("selected stack entry %q no longer exists in stack; use --abort", name)
		}
	}
	sel, err := internal.ResolveSyncSelection(stack, payload.Policy(), internal.SyncSelectionOpts{
		Mode:    mode,
		NewMode: true,
		Feature: feature,
	})
	if err != nil {
		return internal.SyncSelection{}, err
	}
	keep := make(map[string]bool, len(payload.Selected))
	for _, name := range payload.Selected {
		keep[name] = true
	}
	filtered := internal.SyncSelection{Policy: sel.Policy, Names: make(map[string]bool, len(keep))}
	repoSet := make(map[string]bool)
	for _, entry := range sel.Entries {
		if !keep[entry.Name] {
			continue
		}
		filtered.Entries = append(filtered.Entries, entry)
		filtered.Names[entry.Name] = true
		repoSet[entry.Repo] = true
	}
	for repo := range repoSet {
		filtered.Repos = append(filtered.Repos, repo)
	}
	sort.Strings(filtered.Repos)
	return filtered, nil
}

func branchContainsConfiguredParent(worktreesRoot string, stack internal.Stack, child internal.StackEntry) bool {
	parent := internal.GetBranch(stack, child.Base)
	if parent.Name == "" || !sameStackRepo(parent.Repo, child.Repo) {
		return true
	}
	path := externalSyncLayout{WorktreesRoot: worktreesRoot}.WorktreePath(child.Name)
	return internal.RunSilentDir(path, "git", "merge-base", "--is-ancestor", parent.GitBranch(), child.GitBranch()) == nil
}

func isRebaseInProgress(worktreePath string) bool {
	// Check for .git/rebase-merge or .git/rebase-apply
	gitDir := internal.RunSilent("git", "-C", worktreePath, "rev-parse", "--git-dir")
	if gitDir != nil {
		return false
	}
	// Simpler: check if git status shows rebase
	err := internal.RunSilent("git", "-C", worktreePath, "rebase", "--show-current-patch")
	return err == nil
}

func syncFeature(feature string, layout externalSyncLayout, verbose bool) syncResult {
	stack, err := internal.LoadStack(layout.FeaturePath)
	if err != nil {
		fetchQuiet("", "", verbose)
		syncFallback(layout)
		return syncResult{Complete: true}
	}

	repos := internal.UniqueRepos(stack, layout.FeaturePath)
	for repo, wtPath := range repos {
		fetchQuiet(repo, wtPath, verbose)
	}

	sorted, err := internal.TopoSort(stack)
	if err != nil {
		fmt.Printf("Error: %v\n", err)
		return syncResult{}
	}
	return syncWithStack(feature, layout, stack, sorted)
}

// syncFeatureScoped is syncFeature for a new-mode run: the stack is already
// loaded and validated, and the fetch loop is restricted to the repos the
// selection actually touches.
func syncFeatureScoped(feature string, layout externalSyncLayout, verbose bool, stack internal.Stack, run *syncRunContext) syncResult {
	if run.Policy.Fetch == internal.SyncFetchEnabled {
		run.Payload.Stage = internal.SyncStageFetching
		_ = internal.SaveSyncRunState(layout.FeaturePath, run.Payload)
		sub := internal.Stack{Branches: selectedRealEntries(stack, run.Sel)}
		for repo, wtPath := range internal.UniqueRepos(sub, layout.FeaturePath) {
			fetchQuiet(repo, wtPath, verbose)
		}
	}
	sorted, err := internal.TopoSort(stack)
	if err != nil {
		fmt.Printf("Error: %v\n", err)
		return syncResult{}
	}
	return syncWithStackScoped(feature, layout, stack, sorted, nil, run)
}

// selectedRealEntries returns the real StackEntry values of the selection, in
// selection order. Executors never rebuild entries from SyncSelectedEntry:
// that would drop LastBaseSHA and destroy the amend-aware replay.
func selectedRealEntries(stack internal.Stack, sel internal.SyncSelection) []internal.StackEntry {
	out := make([]internal.StackEntry, 0, len(sel.Entries))
	for _, entry := range sel.Entries {
		real := internal.GetBranch(stack, entry.Name)
		if real.Name == "" {
			continue
		}
		out = append(out, real)
	}
	return out
}

// syncRepoContext is the §13.4 rule 3 repo context: the entry's Repo when set,
// otherwise its materialized worktree path, otherwise "".
func syncRepoContext(layout externalSyncLayout, entry internal.StackEntry) string {
	if entry.Repo != "" {
		return entry.Repo
	}
	path := layout.WorktreePath(entry.Name)
	if _, err := os.Stat(path); err == nil {
		return path
	}
	return ""
}

func fetchQuiet(repo, wtPath string, verbose bool) {
	label := "default repo"
	if repo != "" {
		label = repo
	}

	if verbose {
		fmt.Printf("Fetching %s...\n", label)
		if wtPath != "" {
			_ = internal.RunDir(wtPath, "git", "fetch")
		} else if repo != "" {
			_ = internal.RunDir(repo, "git", "fetch")
		} else {
			_ = internal.Run("git", "fetch")
		}
	} else {
		fmt.Printf("Fetching %s... ", label)
		var err error
		if wtPath != "" {
			err = internal.RunSilentDir(wtPath, "git", "fetch")
		} else if repo != "" {
			err = internal.RunSilentDir(repo, "git", "fetch")
		} else {
			err = internal.RunSilent("git", "fetch")
		}
		if err != nil {
			fmt.Println("failed")
		} else {
			fmt.Println("done")
		}
	}
}

package cli

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
)

// ---------------------------------------------------------------------------
// AC 12 / AC 13 — all twelve cells of fetch × propagation × scope, executed in
// both workspace modes against real repositories, real remotes, and (in
// external mode) real linked worktrees. Every stack entry's SHA is asserted in
// every cell, together with the scope invariants and, for every `no-fetch`
// cell, the untouched remote-tracking refs.
// ---------------------------------------------------------------------------

type syncCell struct {
	fetch internal.SyncFetchPolicy
	prop  internal.SyncPropagationPolicy
	scope internal.SyncScopeKind
}

func syncTwelveCells() []syncCell {
	var cells []syncCell
	for _, fetch := range []internal.SyncFetchPolicy{internal.SyncFetchEnabled, internal.SyncFetchDisabled} {
		for _, prop := range []internal.SyncPropagationPolicy{internal.SyncPropagationFull, internal.SyncPropagationLocalOnly} {
			for _, scope := range []internal.SyncScopeKind{internal.SyncScopeAll, internal.SyncScopeOne, internal.SyncScopeSubtree} {
				cells = append(cells, syncCell{fetch: fetch, prop: prop, scope: scope})
			}
		}
	}
	return cells
}

func (c syncCell) name() string {
	return fmt.Sprintf("%s_%s_%s", c.fetch, c.prop, c.scope)
}

// policy is the frozen decision this cell must produce, whichever mode runs it.
func (c syncCell) policy(selector string) internal.SyncRunPolicy {
	p := internal.SyncRunPolicy{Fetch: c.fetch, Propagation: c.prop, ScopeKind: c.scope}
	if c.scope != internal.SyncScopeAll {
		p.Selector = selector
	}
	return p
}

// flags renders the cell as the command line an operator would type. Every cell
// is spelled explicitly, so no cell can silently ride on a mode default.
func (c syncCell) flags(selector string) []string {
	args := []string{"--" + string(c.fetch)}
	switch c.prop {
	case internal.SyncPropagationLocalOnly:
		args = append(args, "--local-only")
	default:
		args = append(args, "--full")
	}
	switch c.scope {
	case internal.SyncScopeOne:
		args = append(args, "--only", selector)
	case internal.SyncScopeSubtree:
		args = append(args, "--from", selector)
	}
	return args
}

func (c syncCell) header(selector string) string {
	p := c.policy(selector)
	return fmt.Sprintf("Sync mode: fetch=%s propagation=%s scope=%s", p.Fetch, p.Propagation, p.ScopeLabel())
}

// cellEntryExpect is the complete expectation for one stack entry in one cell.
type cellEntryExpect struct {
	selected bool // the run considers the entry at all
	skipped  bool // selected, but a local-only anchor: a no-op success
	moved    bool // the branch SHA must differ from its pre-run value
}

// expect maps the three fixture entries onto their per-cell expectation. The
// fixtures are built so that every propagation edge has real work, so
// `selected && !skipped` implies `moved` for every non-anchor entry, and the
// anchor moves only when it is both selected under `full` and given a new base
// by a fetch.
//
// anchorMovesOnFetch is true for external mode, where the anchor's base is the
// remote-tracking ref a fetch advances, and false for checkout mode, where the
// anchor's base is a local branch and the fetch axis only refreshes
// remote-tracking refs (§10.3).
func (c syncCell) expect(anchor, mid, leaf string, anchorMovesOnFetch bool) map[string]cellEntryExpect {
	selected := map[string]bool{mid: true}
	switch c.scope {
	case internal.SyncScopeAll:
		selected[anchor] = true
		selected[leaf] = true
	case internal.SyncScopeSubtree:
		selected[leaf] = true
	}

	out := make(map[string]cellEntryExpect, 3)
	for _, name := range []string{anchor, mid, leaf} {
		e := cellEntryExpect{selected: selected[name]}
		switch {
		case !e.selected:
		case name == anchor && c.prop == internal.SyncPropagationLocalOnly:
			e.skipped = true
		case name == anchor:
			e.moved = !anchorMovesOnFetch || c.fetch == internal.SyncFetchEnabled
		default:
			e.moved = true
		}
		out[name] = e
	}
	return out
}

// ---------------------------------------------------------------------------
// External mode
// ---------------------------------------------------------------------------

// cellFixture prepares a linear external fixture in which every edge has real
// work: the anchor's remote base is ahead of the local remote-tracking ref
// (visible only through a fetch), the anchor is ahead of its child, and that
// child is ahead of the leaf.
type cellFixture struct {
	*scopedFixture
	trackingBefore string // refs/remotes/origin/master before the run
	remoteHead     string // refs/heads/master on the bare remote
}

func newCellFixture(t *testing.T) *cellFixture {
	t.Helper()
	f := newScopedFixture(t)

	// Local work: root ahead of parent, parent ahead of child.
	writeAndCommit(t, f.wt("root"), "root-v2.txt", "root-v2\n", "root v2")
	writeAndCommit(t, f.wt("parent"), "parent-v2.txt", "parent-v2\n", "parent v2")

	// Remote work the local repository cannot see without fetching: push a new
	// master commit, then rewind the remote-tracking ref by hand.
	tracking := gitOutput(t, f.repo, "rev-parse", "refs/remotes/origin/master")
	writeAndCommit(t, f.repo, "upstream.txt", "upstream\n", "upstream")
	gitRun(t, f.repo, "push", "origin", "master")
	remoteHead := gitOutput(t, f.remote, "rev-parse", "refs/heads/master")
	gitRun(t, f.repo, "update-ref", "refs/remotes/origin/master", tracking)

	return &cellFixture{scopedFixture: f, trackingBefore: tracking, remoteHead: remoteHead}
}

func (f *cellFixture) shas(t *testing.T) map[string]string {
	t.Helper()
	out := make(map[string]string, 3)
	for _, name := range []string{"root", "parent", "child"} {
		out[name] = gitOutput(t, f.repo, "rev-parse", "refs/heads/"+name)
	}
	return out
}

