func TestSyncRunGuard_LiveGuardIsNeverStolen(t *testing.T) {
	dir := t.TempDir()
	restore := stubSyncProcessAlive(t, func(int) bool { return true })
	defer restore()
	if err := ClaimSyncRunGuard(dir, "first"); err != nil {
