func TestSyncRunGuard_StaleGuardWithPayloadRefused(t *testing.T) {
	dir := t.TempDir()
	restore := stubSyncProcessAlive(t, func(int) bool { return false })
	defer restore()
	if err := ClaimSyncRunGuard(dir, "first"); err != nil {
