func TestClassifyExternalSyncState_TwelveCells(t *testing.T) {
	cases := []struct {
		name  string
		setup func(t *testing.T, dir string)
		cell  SyncStateCell
	}{
		{"1-absent-absent", func(t *testing.T, dir string) {}, 1},
		{"2-absent-valid", func(t *testing.T, dir string) { writeValidPayload(t, dir, "child", "tok") }, 2},
		{"3-absent-unreadable", func(t *testing.T, dir string) { writeUnreadablePayload(t, dir) }, 3},
		{"4-sentinel-absent", func(t *testing.T, dir string) { writeLegacySentinel(t, dir) }, 4},
		{"5-sentinel-valid", func(t *testing.T, dir string) {
			writeLegacySentinel(t, dir)
			writeValidPayload(t, dir, "child", "tok")
		}, 5},
		{"6-sentinel-unreadable", func(t *testing.T, dir string) {
			writeLegacySentinel(t, dir)
			writeUnreadablePayload(t, dir)
		}, 6},
		{"7-real-absent", func(t *testing.T, dir string) { writeRealLegacy(t, dir, "parent") }, 7},
		{"8-real-valid", func(t *testing.T, dir string) {
			writeRealLegacy(t, dir, "parent")
			writeValidPayload(t, dir, "child", "tok")
		}, 8},
		{"9-real-unreadable", func(t *testing.T, dir string) {
			writeRealLegacy(t, dir, "parent")
			writeUnreadablePayload(t, dir)
		}, 9},
		{"10-corrupt-absent", func(t *testing.T, dir string) { writeCorruptLegacy(t, dir) }, 10},
		{"11-corrupt-valid", func(t *testing.T, dir string) {
			writeCorruptLegacy(t, dir)
			writeValidPayload(t, dir, "child", "tok")
		}, 11},
		{"12-corrupt-unreadable", func(t *testing.T, dir string) {
			writeCorruptLegacy(t, dir)
			writeUnreadablePayload(t, dir)
		}, 12},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			dir := t.TempDir()
			tc.setup(t, dir)
			st := ClassifyExternalSyncState(dir, SyncClassifyOpts{AlwaysReadGuard: true, Alive: func(int) bool { return false }})
			if st.Cell != tc.cell {
				t.Fatalf("cell = %d, want %d", st.Cell, tc.cell)
			}
			// An empty legacy failed_branch is real legacy state, never a sentinel.
			if tc.cell == 4 || tc.cell == 5 || tc.cell == 6 {
				if st.Marker != cellMarker {
					t.Fatalf("sentinel cells must expose the marker; got %q", st.Marker)
				}
			} else if st.Marker != "" {
				t.Fatalf("non-sentinel cell %d exposed marker %q", tc.cell, st.Marker)
			}
		})
	}
}

func TestClassifyExternalSyncState_EmptyFailedBranchIsRealLegacy(t *testing.T) {
	dir := t.TempDir()
	writeRealLegacy(t, dir, "")
	st := ClassifyExternalSyncState(dir, SyncClassifyOpts{})
	if st.Cell != 7 {
		t.Fatalf("an empty failed_branch is today's stale-edge state (cell 7); got %d", st.Cell)
	}
}

func TestClassifyExternalSyncState_GuardLiveness(t *testing.T) {
	dir := t.TempDir()
	writeLegacySentinel(t, dir)
	writeValidPayload(t, dir, "child", "tok")
	writeGuardFile(t, dir, 4242, "tok")

	live := ClassifyExternalSyncState(dir, SyncClassifyOpts{Alive: func(pid int) bool { return pid == 4242 }})
	if !live.GuardLive || live.Guard == nil || live.Guard.PID != 4242 {
		t.Fatalf("expected a live owning guard, got %+v", live.Guard)
	}
	stale := ClassifyExternalSyncState(dir, SyncClassifyOpts{Alive: func(int) bool { return false }})
	if stale.GuardLive {
		t.Fatal("a dead PID must classify as stale")
	}
	if stale.Cell != 5 {
		t.Fatal("the guard is precedence and context, never a cell axis")
	}

	// A foreign token is never authoritative, even when the PID is alive.
	writeGuardFile(t, dir, 4242, "other")
	foreign := ClassifyExternalSyncState(dir, SyncClassifyOpts{Alive: func(int) bool { return true }})
	if foreign.GuardLive {
		t.Fatal("a guard whose token does not match the payload is never live-owning")
	}
	if !foreign.GuardForeign() {
		t.Fatal("GuardForeign must report the token mismatch")
	}
}

func TestClassifyExternalSyncState_GuardReadGating(t *testing.T) {
	dir := t.TempDir()
	writeGuardFile(t, dir, 4242, "tok")

	// Cell 1 with no payload and no sentinel: a no-flag run never opens the
	// guard, not even to Lstat it.
	quiet := ClassifyExternalSyncState(dir, SyncClassifyOpts{})
	if quiet.HasGuardFile() {
		t.Fatal("a no-flag run with no payload and no sentinel must not consult the guard")
	}
	loud := ClassifyExternalSyncState(dir, SyncClassifyOpts{AlwaysReadGuard: true, Alive: func(int) bool { return true }})
	if loud.Guard == nil {
		t.Fatal("AlwaysReadGuard must open the guard")
	}
}

func TestClassifyExternalSyncState_SymlinkFacts(t *testing.T) {
	if os.Getenv("TWS_SKIP_SYMLINK") == "1" {
		t.Skip("symlinks unavailable")
	}
	dir := t.TempDir()
	target := filepath.Join(dir, "elsewhere.yaml")
	if err := os.WriteFile(target, []byte("state_version: 2\nfeature: auth\n"), 0600); err != nil {
		t.Fatal(err)
	}
	if err := os.Symlink(target, SyncRunStatePath(dir)); err != nil {
		t.Skipf("symlink unsupported: %v", err)
	}
	if err := os.Symlink(target, SyncRunGuardPath(dir)); err != nil {
		t.Fatal(err)
	}
	st := ClassifyExternalSyncState(dir, SyncClassifyOpts{AlwaysReadGuard: true})
	if !st.PayloadSymlink || st.Payload != nil || st.PayloadErr == nil {
		t.Fatalf("a payload symlink is recorded, never followed: %+v", st)
	}
	if !st.GuardSymlink || st.Guard != nil || st.GuardLive {
		t.Fatalf("a guard symlink is recorded, never followed: %+v", st)
	}
	if st.Cell != 3 {
		t.Fatalf("a symlinked payload classifies as unreadable (cell 3); got %d", st.Cell)
	}
	if st.PayloadPath != SyncRunStatePath(dir) || st.GuardPath != SyncRunGuardPath(dir) || st.LegacyPath != SyncStatePath(dir) {
		t.Fatal("the classifier must record the three consulted paths")
	}
}

func TestClassifyExternalSyncState_LegacySymlinkIsRecordedAndStillFollowed(t *testing.T) {
	dir := t.TempDir()
	target := filepath.Join(dir, "legacy.yaml")
	s := NewSyncState()
	s.FailedBranch = "parent"
	if err := SaveSyncState(filepath.Dir(target), s); err != nil {
		t.Fatal(err)
	}
	// SaveSyncState writes .sync-state.yaml; move it aside and link to it.
	if err := os.Rename(SyncStatePath(dir), target); err != nil {
		t.Fatal(err)
	}
	if err := os.Symlink(target, SyncStatePath(dir)); err != nil {
		t.Skipf("symlink unsupported: %v", err)
	}
	st := ClassifyExternalSyncState(dir, SyncClassifyOpts{})
	if !st.LegacySymlink {
		t.Fatal("the legacy symlink fact must be recorded")
	}
	if st.Legacy == nil || st.Legacy.FailedBranch != "parent" {
		t.Fatal("the legacy read still follows the link — frozen behaviour")
	}
	if st.Cell != 7 {
		t.Fatalf("cell = %d, want 7", st.Cell)
	}
}

func TestSyncRunState_PathsAreJoinedFromOneRoot(t *testing.T) {
	dir := filepath.Join("a", "b")
	if SyncRunStatePath(dir) != filepath.Join(dir, ".sync-state.v2.yaml") {
		t.Fatal("payload path")
	}
	if SyncRunGuardPath(dir) != filepath.Join(dir, ".sync-run.lock") {
		t.Fatal("guard path")
	}
	if SyncStatePath(dir) != filepath.Join(dir, ".sync-state.yaml") {
		t.Fatal("legacy path")
	}
}

package internal

import (
	"fmt"
	"sort"
)

// ---------------------------------------------------------------------------
// sync-modes — the shared selector and plan model (spec §5).
//
// One model, one resolution function, shared by both workspace modes. There is
// no second topological sort, no second descendant walker, no second parent
// lookup, and no second ancestry rule.
// ---------------------------------------------------------------------------

// SyncFetchPolicy is axis F.
type SyncFetchPolicy string

const (
	SyncFetchEnabled  SyncFetchPolicy = "fetch"
	SyncFetchDisabled SyncFetchPolicy = "no-fetch"
)

// SyncPropagationPolicy is axis P.
type SyncPropagationPolicy string

const (
	SyncPropagationFull      SyncPropagationPolicy = "full"
	SyncPropagationLocalOnly SyncPropagationPolicy = "local-only"
)

// SyncScopeKind is axis S.
type SyncScopeKind string

const (
	SyncScopeAll     SyncScopeKind = "all"
	SyncScopeOne     SyncScopeKind = "one"
	SyncScopeSubtree SyncScopeKind = "subtree"
)

// SyncRunPolicy is the frozen decision of one run. It is persisted verbatim.
type SyncRunPolicy struct {
	Fetch       SyncFetchPolicy       `yaml:"fetch_policy"`
	Propagation SyncPropagationPolicy `yaml:"propagation_policy"`
	ScopeKind   SyncScopeKind         `yaml:"scope_kind"`
	Selector    string                `yaml:"scope_selector,omitempty"` // logical StackEntry.Name
}

// SyncSelectionRole classifies one selected entry.
type SyncSelectionRole string

const (
	// SyncRoleAnchor: base is a literal ref, empty, or a stack entry in a
	// different repo. Never rebased under local-only.
	SyncRoleAnchor SyncSelectionRole = "anchor"
	// SyncRolePropagated: base names another stack entry in the same repo.
	SyncRolePropagated SyncSelectionRole = "propagated"
)

// SyncSelectedEntry is one resolved member of the selection, in the order
// TopoSort returned (parent before child; sibling order unspecified, §3.7).
//
// It deliberately carries no LastBaseSHA: no executor may reconstruct
// StackEntry values from the selection, because that would silently drop
// LastBaseSHA and destroy the amend-aware `--onto <base> <LastBaseSHA>` replay.
type SyncSelectedEntry struct {
	Name       string
	GitBranch  string
	Repo       string
	Base       string
	Role       SyncSelectionRole
	ParentName string
	Archived   bool
}

// SyncSelection is the whole resolved plan-independent selection.
type SyncSelection struct {
	Policy  SyncRunPolicy
	Entries []SyncSelectedEntry
	Names   map[string]bool
	Repos   []string
}

// SyncSelectionOpts carries everything the validator needs that the policy does
// not. It is deliberately tiny and value-only: resolution stays pure.
type SyncSelectionOpts struct {
	Mode    WorkspaceMode // ModeExternal or ModeCheckout; selects the checkout-only rules
	NewMode bool          // any trigger flag was Changed; selects the new-mode-only rules
	Feature string        // resolved feature name, interpolated into the I10/I11 messages
}

// SameStackRepo is the single cross-repo predicate. An empty string names the
// default repository.
func SameStackRepo(a, b string) bool {
	if a == "" && b == "" {
		return true
	}
	return a == b
}

// IsAnchorSelection reports whether the selection holds no propagation edge at
// all, which is the local-only no-op condition (D3).
func (s SyncSelection) IsAnchorSelection() bool {
	for _, e := range s.Entries {
		if e.Role == SyncRolePropagated {
			return false
		}
	}
	return true
}

// Anchors returns the selected anchors in selection order.
func (s SyncSelection) Anchors() []SyncSelectedEntry {
	var out []SyncSelectedEntry
	for _, e := range s.Entries {
		if e.Role == SyncRoleAnchor {
			out = append(out, e)
		}
	}
	return out
}

// Role reports the role of one selected entry. Unselected names report the
// zero value, which no executor may treat as a role.
func (s SyncSelection) Role(name string) SyncSelectionRole {
	for _, e := range s.Entries {
		if e.Name == name {
			return e.Role
		}
	}
	return ""
}

// SelectedNames returns the selection's logical names in selection order. It is
// what the v2 payload persists as `selected`.
func (s SyncSelection) SelectedNames() []string {
	out := make([]string, 0, len(s.Entries))
	for _, e := range s.Entries {
		out = append(out, e.Name)
	}
	return out
}

// Scoped reports whether the run restricts the selection below the whole stack.
func (p SyncRunPolicy) Scoped() bool { return p.ScopeKind != SyncScopeAll }

// ScopeLabel renders the scope for the §3.7 header.
func (p SyncRunPolicy) ScopeLabel() string {
	switch p.ScopeKind {
	case SyncScopeOne:
		return "only:" + p.Selector
	case SyncScopeSubtree:
		return "subtree:" + p.Selector
	default:
		return string(SyncScopeAll)
	}
}

// ResolveSyncSelection is the one resolution function. It owns I10, I11, I12,
// and I13 — every selection-validity rule — and no caller re-implements,
// re-checks, or supplements them.
//
// It performs no Git command, no filesystem access, no path resolution, and no
// I/O: opts.Feature is consumed as a message value only.
func ResolveSyncSelection(stack Stack, policy SyncRunPolicy, opts SyncSelectionOpts) (SyncSelection, error) {
	sorted, err := TopoSort(stack)
	if err != nil {
		return SyncSelection{}, err
	}

	members := make(map[string]bool, len(sorted))
	switch policy.ScopeKind {
	case SyncScopeAll:
		for _, e := range sorted {
			members[e.Name] = true
		}
	case SyncScopeOne:
		if !HasBranch(stack, policy.Selector) {
			return SyncSelection{}, unknownStackEntryError(policy.Selector, opts.Feature)
		}
		members[policy.Selector] = true
	case SyncScopeSubtree:
		if !HasBranch(stack, policy.Selector) {
			return SyncSelection{}, unknownStackEntryError(policy.Selector, opts.Feature)
		}
		members[policy.Selector] = true
		for name := range Descendants(stack, policy.Selector) {
			members[name] = true
		}
	default:
		return SyncSelection{}, fmt.Errorf("unknown sync scope %q", policy.ScopeKind)
	}

	if policy.ScopeKind != SyncScopeAll {
		if GetBranch(stack, policy.Selector).Archived {
			return SyncSelection{}, archivedStackEntryError(policy.Selector, opts.Feature)
		}
	}

	sel := SyncSelection{Policy: policy, Names: make(map[string]bool, len(members))}
	repoSet := make(map[string]bool)
	for _, entry := range sorted {
		if !members[entry.Name] {
			continue
		}
		selected := SyncSelectedEntry{
			Name:      entry.Name,
			GitBranch: entry.GitBranch(),
			Repo:      entry.Repo,
			Base:      entry.Base,
			Archived:  entry.Archived,
			Role:      SyncRoleAnchor,
		}
		if parent := GetBranch(stack, entry.Base); parent.Name != "" && SameStackRepo(parent.Repo, entry.Repo) {
			selected.Role = SyncRolePropagated
			selected.ParentName = parent.Name
		}
		sel.Entries = append(sel.Entries, selected)
		sel.Names[entry.Name] = true
		repoSet[entry.Repo] = true
	}

	if opts.Mode == ModeCheckout {
		for _, e := range sel.Entries {
			if !SameStackRepo(e.Repo, "") {
				return SyncSelection{}, fmt.Errorf("stack entry %q belongs to repository %q; checkout sync is single-repository (cross-repo-unsupported)", e.Name, e.Repo)
			}
		}
	}

	if opts.NewMode {
		seen := make(map[string]string, len(sel.Entries))
		for _, e := range sel.Entries {
			if first, ok := seen[e.GitBranch]; ok {
				return SyncSelection{}, fmt.Errorf("stack entries %q and %q share Git branch %q; select one of them with --only", first, e.Name, e.GitBranch)
			}
			seen[e.GitBranch] = e.Name
		}
	}

	for repo := range repoSet {
		sel.Repos = append(sel.Repos, repo)
	}
	sort.Strings(sel.Repos)
	return sel, nil
}

// unknownStackEntryError is the single I10 format string.
func unknownStackEntryError(selector, feature string) error {
	return fmt.Errorf("unknown stack entry %q in feature %q; run: tws stack status %s", selector, feature, feature)
}

// archivedStackEntryError is the single I11 format string.
func archivedStackEntryError(selector, feature string) error {
	return fmt.Errorf("stack entry %q is archived; restore it with: tws new %s %s", selector, feature, selector)
}

package internal

import (
	"strings"
	"testing"
)

// ---------------------------------------------------------------------------
// ResolveSyncSelection is pure over (Stack, SyncRunPolicy, SyncSelectionOpts):
// no Git, no filesystem, no path resolution. Every test below is a literal
// table with no t.TempDir and no repository.
// ---------------------------------------------------------------------------

func syncTestStack() Stack {
	return Stack{Branches: []StackEntry{
		{Name: "root", Base: "master"},
		{Name: "parent", Base: "root"},
		{Name: "child", Base: "parent"},
		{Name: "sibling", Base: "root"},
		{Name: "old", Base: "root", Archived: true},
		{Name: "other-repo", Base: "root", Repo: "/repos/other"},
	}}
}

func policyAll() SyncRunPolicy {
	return SyncRunPolicy{Fetch: SyncFetchEnabled, Propagation: SyncPropagationFull, ScopeKind: SyncScopeAll}
}

func policyOne(name string) SyncRunPolicy {
	p := policyAll()
	p.ScopeKind = SyncScopeOne
	p.Selector = name
	return p
}

func policySubtree(name string) SyncRunPolicy {
	p := policyAll()
	p.ScopeKind = SyncScopeSubtree
	p.Selector = name
	return p
}

func newModeOpts(mode WorkspaceMode) SyncSelectionOpts {
	return SyncSelectionOpts{Mode: mode, NewMode: true, Feature: "auth"}
}

func TestSyncSelection_ScopeMembership(t *testing.T) {
	stack := syncTestStack()
	cases := []struct {
		name   string
		policy SyncRunPolicy
		want   []string
	}{
		{"all", policyAll(), []string{"root", "parent", "child", "sibling", "old", "other-repo"}},
		{"one", policyOne("parent"), []string{"parent"}},
		{"subtree-includes-root", policySubtree("parent"), []string{"parent", "child"}},
		{"subtree-whole", policySubtree("root"), []string{"root", "parent", "child", "sibling", "old", "other-repo"}},
		{"one-leaf", policyOne("child"), []string{"child"}},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			sel, err := ResolveSyncSelection(stack, tc.policy, newModeOpts(ModeExternal))
			if err != nil {
				t.Fatalf("ResolveSyncSelection: %v", err)
			}
			if len(sel.Entries) != len(tc.want) {
				t.Fatalf("selected %v, want %v", sel.SelectedNames(), tc.want)
			}
			for _, name := range tc.want {
				if !sel.Names[name] {
					t.Fatalf("expected %q in selection %v", name, sel.SelectedNames())
				}
			}
		})
	}
}

func TestSyncSelection_ParentBeforeChild(t *testing.T) {
	sel, err := ResolveSyncSelection(syncTestStack(), policyAll(), newModeOpts(ModeExternal))
	if err != nil {
		t.Fatal(err)
	}
	pos := make(map[string]int, len(sel.Entries))
	for i, e := range sel.Entries {
		pos[e.Name] = i
	}
	// Only parent-before-child is contracted; sibling order is unspecified.
	for _, edge := range [][2]string{{"root", "parent"}, {"parent", "child"}, {"root", "sibling"}} {
		if pos[edge[0]] >= pos[edge[1]] {
			t.Fatalf("%s must precede %s in %v", edge[0], edge[1], sel.SelectedNames())
		}
	}
}

func TestSyncSelection_Roles(t *testing.T) {
	sel, err := ResolveSyncSelection(syncTestStack(), policyAll(), newModeOpts(ModeExternal))
	if err != nil {
		t.Fatal(err)
	}
	want := map[string]SyncSelectionRole{
		"root":       SyncRoleAnchor,     // literal base
		"parent":     SyncRolePropagated, // same-repo stack parent
		"child":      SyncRolePropagated,
		"sibling":    SyncRolePropagated,
		"other-repo": SyncRoleAnchor, // stack parent in a different repo
	}
	for name, role := range want {
		if got := sel.Role(name); got != role {
			t.Fatalf("role(%q) = %q, want %q", name, got, role)
		}
	}
	for _, e := range sel.Entries {
		if e.Role == SyncRolePropagated && e.ParentName == "" {
			t.Fatalf("propagated entry %q carries no parent name", e.Name)
		}
		if e.Role == SyncRoleAnchor && e.ParentName != "" {
			t.Fatalf("anchor %q carries parent name %q", e.Name, e.ParentName)
		}
	}
}

func TestSyncSelection_AnchorOnlySelectionIsNoOp(t *testing.T) {
	sel, err := ResolveSyncSelection(syncTestStack(), policyOne("root"), newModeOpts(ModeExternal))
	if err != nil {
		t.Fatal(err)
	}
	if !sel.IsAnchorSelection() {
		t.Fatal("a root-only selection holds no propagation edge")
	}
	if len(sel.Anchors()) != 1 {
		t.Fatalf("expected one anchor, got %v", sel.Anchors())
	}

	sel, err = ResolveSyncSelection(syncTestStack(), policyOne("child"), newModeOpts(ModeExternal))
	if err != nil {
		t.Fatal(err)
	}
	if sel.IsAnchorSelection() {
		t.Fatal("a child-only selection holds a propagation edge")
	}
}

func TestSyncSelection_UnknownSelectorI10(t *testing.T) {
	_, err := ResolveSyncSelection(syncTestStack(), policyOne("nope"), newModeOpts(ModeExternal))
	if err == nil {
		t.Fatal("expected I10")
	}
	want := `unknown stack entry "nope" in feature "auth"; run: tws stack status auth`
	if err.Error() != want {
		t.Fatalf("I10 = %q, want %q", err.Error(), want)
	}
	if _, err := ResolveSyncSelection(syncTestStack(), policySubtree("nope"), newModeOpts(ModeCheckout)); err == nil || err.Error() != want {
		t.Fatalf("I10 must be identical for --from and in checkout mode; got %v", err)
	}
}

func TestSyncSelection_ArchivedSelectorI11(t *testing.T) {
	_, err := ResolveSyncSelection(syncTestStack(), policyOne("old"), newModeOpts(ModeExternal))
	if err == nil {
		t.Fatal("expected I11")
	}
	want := `stack entry "old" is archived; restore it with: tws new auth old`
	if err.Error() != want {
		t.Fatalf("I11 = %q, want %q", err.Error(), want)
	}
}

func TestSyncSelection_ArchivedClosureMemberIsNotRefused(t *testing.T) {
	// `old` is archived but is only a closure member, never the named selector.
	sel, err := ResolveSyncSelection(syncTestStack(), policySubtree("root"), newModeOpts(ModeExternal))
	if err != nil {
		t.Fatalf("closure members must not be filtered on Archived: %v", err)
	}
	if !sel.Names["old"] {
		t.Fatal("archived closure member must stay in the selection")
	}
}

func TestSyncSelection_CrossRepoI12CheckoutOnly(t *testing.T) {
	_, err := ResolveSyncSelection(syncTestStack(), policyAll(), newModeOpts(ModeCheckout))
	if err == nil {
		t.Fatal("expected I12 in checkout mode")
	}
	want := `stack entry "other-repo" belongs to repository "/repos/other"; checkout sync is single-repository (cross-repo-unsupported)`
	if err.Error() != want {
		t.Fatalf("I12 = %q, want %q", err.Error(), want)
	}
	if _, err := ResolveSyncSelection(syncTestStack(), policyAll(), newModeOpts(ModeExternal)); err != nil {
		t.Fatalf("external mode never refuses a cross-repo entry: %v", err)
	}
}

func TestSyncSelection_DuplicateGitBranchI13(t *testing.T) {
	stack := Stack{Branches: []StackEntry{
		{Name: "root", Base: "master"},
		{Name: "work", Base: "root", Branch: "user/work"},
		{Name: "copy", Base: "root", Branch: "user/work"},
	}}
	_, err := ResolveSyncSelection(stack, policyAll(), newModeOpts(ModeExternal))
	if err == nil {
		t.Fatal("expected I13")
	}
	if !strings.Contains(err.Error(), `share Git branch "user/work"; select one of them with --only`) {
		t.Fatalf("I13 = %q", err.Error())
	}
	// The frozen path never calls the resolver, so NewMode false suppresses it.
	if _, err := ResolveSyncSelection(stack, policyAll(), SyncSelectionOpts{Mode: ModeExternal, Feature: "auth"}); err != nil {
		t.Fatalf("I13 is a new-mode rule only: %v", err)
	}
	// Selecting one of the two is accepted.
	if _, err := ResolveSyncSelection(stack, policyOne("work"), newModeOpts(ModeExternal)); err != nil {
		t.Fatalf("--only must resolve the duplicate: %v", err)
	}
}

func TestSyncSelection_GitBranchIdentity(t *testing.T) {
	stack := Stack{Branches: []StackEntry{
		{Name: "root", Base: "master"},
		{Name: "work", Base: "root", Branch: "user/work"},
	}}
	sel, err := ResolveSyncSelection(stack, policyOne("work"), newModeOpts(ModeExternal))
	if err != nil {
		t.Fatal(err)
	}
	if sel.Entries[0].GitBranch != "user/work" {
		t.Fatalf("GitBranch = %q, want user/work", sel.Entries[0].GitBranch)
	}
	if sel.Entries[0].Name != "work" {
		t.Fatalf("selector identity is the logical Name, got %q", sel.Entries[0].Name)
	}
}

func TestSyncSelection_ReposSortedWithDefaultFirst(t *testing.T) {
	stack := Stack{Branches: []StackEntry{
		{Name: "root", Base: "master"},
		{Name: "b", Base: "root", Repo: "/repos/zed"},
		{Name: "a", Base: "root", Repo: "/repos/alpha"},
	}}
	sel, err := ResolveSyncSelection(stack, policyAll(), newModeOpts(ModeExternal))
	if err != nil {
		t.Fatal(err)
	}
	want := []string{"", "/repos/alpha", "/repos/zed"}
	if len(sel.Repos) != len(want) {
		t.Fatalf("repos = %v, want %v", sel.Repos, want)
	}
	for i := range want {
		if sel.Repos[i] != want[i] {
			t.Fatalf("repos = %v, want %v", sel.Repos, want)
		}
	}
}

func TestSyncSelection_ScopeLabelAndScoped(t *testing.T) {
	cases := []struct {
		policy SyncRunPolicy
		label  string
		scoped bool
	}{
		{policyAll(), "all", false},
		{policyOne("parent"), "only:parent", true},
		{policySubtree("parent"), "subtree:parent", true},
	}
	for _, tc := range cases {
		if got := tc.policy.ScopeLabel(); got != tc.label {
			t.Fatalf("ScopeLabel = %q, want %q", got, tc.label)
		}
		if got := tc.policy.Scoped(); got != tc.scoped {
			t.Fatalf("Scoped(%s) = %v, want %v", tc.label, got, tc.scoped)
		}
	}
}

func TestSameStackRepo(t *testing.T) {
	cases := []struct {
		a, b string
		want bool
	}{
		{"", "", true},
		{"/x", "/x", true},
		{"", "/x", false},
		{"/x", "", false},
		{"/x", "/y", false},
	}
	for _, tc := range cases {
		if got := SameStackRepo(tc.a, tc.b); got != tc.want {
			t.Fatalf("SameStackRepo(%q,%q) = %v, want %v", tc.a, tc.b, got, tc.want)
		}
	}
}

func TestSyncSelection_TopoSortErrorPropagates(t *testing.T) {
	cyclic := Stack{Branches: []StackEntry{
		{Name: "a", Base: "b"},
		{Name: "b", Base: "a"},
	}}
	if _, err := ResolveSyncSelection(cyclic, policyAll(), newModeOpts(ModeExternal)); err == nil {
		t.Fatal("a cyclic stack must propagate the TopoSort error verbatim")
	}
}

func TestSyncSelection_SelectedNamesMirrorEntries(t *testing.T) {
	sel, err := ResolveSyncSelection(syncTestStack(), policySubtree("parent"), newModeOpts(ModeExternal))
	if err != nil {
		t.Fatal(err)
	}
	names := sel.SelectedNames()
	if len(names) != len(sel.Entries) {
		t.Fatalf("SelectedNames %v does not mirror Entries", names)
	}
	for i := range names {
		if names[i] != sel.Entries[i].Name {
			t.Fatalf("SelectedNames order diverges from Entries at %d", i)
		}
	}
	if sel.Role("not-selected") != "" {
		t.Fatal("Role of an unselected name must be the zero value")
	}
}

package internal

import (
	"encoding/json"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

// ---------------------------------------------------------------------------
// tws status is a read-only, marker-aware projection of the external sync
// state (§11.1). It never mutates, never exposes the marker, and never adds a
// key, an enum value, or a schema version.
// ---------------------------------------------------------------------------

const statusMarker = "tws-scoped-sync-0123456789abcdef0123456789abcdef.lock"

func writeStatusSentinel(t *testing.T, featurePath string) {
	t.Helper()
	s := NewSyncState()
	s.FailedBranch = statusMarker
	s.Pending = []string{}
	s.Completed = []string{}
	s.Skipped = []string{}
	if err := SaveSyncState(featurePath, s); err != nil {
		t.Fatal(err)
	}
}

func writeStatusPayload(t *testing.T, featurePath, failed, token string) {
	t.Helper()
	p := NewSyncRunState("auth", statusMarker, token, SyncRunPolicy{
		Fetch: SyncFetchEnabled, Propagation: SyncPropagationFull, ScopeKind: SyncScopeOne, Selector: failed,
	})
	p.Selected = []string{failed}
	p.Pending = []string{failed}
	p.Completed = []string{}
	p.FailedBranch = failed
	p.Stage = SyncStageFailed
	if err := SaveSyncRunState(featurePath, p); err != nil {
		t.Fatal(err)
	}
}

func writeStatusGuard(t *testing.T, featurePath string, pid int, token string) {
	t.Helper()
	body := "pid: " + itoa(pid) + "\ncreated: \"2026-01-01T00:00:00Z\"\ntoken: \"" + token + "\"\nstate_version: 2\n"
	if err := os.WriteFile(SyncRunGuardPath(featurePath), []byte(body), 0600); err != nil {
		t.Fatal(err)
	}
}

func syncStatusFileHashes(t *testing.T, featurePath string) map[string]string {
	t.Helper()
	out := make(map[string]string)
	for _, path := range []string{SyncStatePath(featurePath), SyncRunStatePath(featurePath), SyncRunGuardPath(featurePath)} {
		data, err := os.ReadFile(path)
		if err != nil {
			continue
		}
		out[path] = string(data)
	}
	return out
}

func TestAgentStatus_ScopedSyncStaleProjectsRealNames(t *testing.T) {
	ws, featurePath := setupExternalStatusWorkspace(t, "auth", []StackEntry{{Name: "api", Base: "main"}})
	writeStatusSentinel(t, featurePath)
	writeStatusPayload(t, featurePath, "api", "tok")
	writeStatusGuard(t, featurePath, 999002, "tok")
	before := syncStatusFileHashes(t, featurePath)

	proc := fakeProcessProber{probe: map[int]ProcessLiveness{999002: ProcessDead}}
	r := buildStatus(t, ws, statusOpts(proc, nil))

	f := findFeature(t, r, "auth")
	if f.Sync == nil || f.Sync.Kind != "external" {
		t.Fatalf("sync projection = %+v", f.Sync)
	}
	if f.Sync.FailedBranch == nil || *f.Sync.FailedBranch != "api" {
		t.Fatalf("the projection must name the REAL entry, got %+v", f.Sync.FailedBranch)
	}
	if f.Sync.Liveness == nil || *f.Sync.Liveness != "stale" {
		t.Fatalf("liveness = %+v, want stale", f.Sync.Liveness)
	}
	if f.Sync.LockPID == nil || *f.Sync.LockPID != 999002 {
		t.Fatalf("lock_pid = %+v", f.Sync.LockPID)
	}
	if hasIssue(r, IssueSyncStale) == nil {
		t.Fatalf("expected sync-stale, got %v", issueCodes(r))
	}
	assertNoMarkerAnywhere(t, r)

	if after := syncStatusFileHashes(t, featurePath); len(after) != len(before) {
		t.Fatal("status must not delete state")
	} else {
		for path, body := range before {
			if after[path] != body {
				t.Fatalf("status rewrote %s", path)
			}
		}
	}
}

